-- The real club directory, seeded locally.
--
-- Generated from uploads/clubs.json (86 clubs) so the local stack carries the
-- same catalogue production serves. Without this the dashboards, browse view,
-- and quiz all render against an empty table locally.
--
-- Regenerate after changing clubs.json rather than editing by hand.
-- Loads before seed.sql, which references several of these ids.
-- Generated 2026-08-22.

insert into public.clubs (
  id, name, category, advisor, description, target_audience, detailed_description,
  meeting_location, meeting_days, meeting_time, is_student_led,
  interests, scores, instagram, email, phone, photos
) values
  ('aerospace-and-aeronautical-group', 'Aerospace and Aeronautical Group', 'CTE', 'Clark Doten', 'We are a group of students who strive to teach others the basics of sky- and space-related mechanics, such as planes and rockets. We explain how things like rockets and airplanes are able to function.', 'Students interested in aviation and aerospace technologies.', 'We are a group of students who strive to teach others the basics of sky- and space-related mechanics, such as planes and rockets. We explain how things like rockets and airplanes are able to function.', 'C406 (Mr. Doten''s room)', 'Tuesdays', '3:30-4:30 p.m.', true, array['Aviation', 'Aerospace technologies', 'How they work', 'What they do', 'Why they are important']::text[], '{"science_stem": 5, "arts_creative": 0, "health_medical": 0, "competitiveness": 0, "performing_arts": 0, "time_commitment": 3, "world_languages": 0, "trades_technical": 0, "community_service": 0, "cultural_identity": 0, "sports_recreation": 0, "team_vs_individual": 3, "academic_competition": 0, "computer_science_tech": 1, "leadership_government": 0, "leadership_opportunity": 1, "social_special_interest": 2, "public_speaking_emphasis": 2, "writing_media_journalism": 0, "business_entrepreneurship": 0, "environmental_sustainability": 0}'::jsonb, 'wayzataaerospaceandnauticgroup', 'armstlam000@isd284.com, clark.doten@wayzataschools.org', null, '["https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/aerospace-and-aeronautical-group-1.png", "https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/aerospace-and-aeronautical-group-2.png"]'::jsonb),
  ('aha-american-heart-association', 'AHA: American Heart Association', 'CTE', 'Clarice Jorenby', 'We are a student-led club focused on cardiology, heart health awareness, and hands-on community action. Our purpose is to teach students life-saving skills like CPR and to raise awareness for better heart health within our school community, along with hosting guest speakers when possible. We are partnered with the American Heart Association.', 'Students interested in health, CPR training, and community health education.', 'We are a student-led club focused on cardiology, heart health awareness, and hands-on community action. Our purpose is to teach students life-saving skills like CPR and to raise awareness for better heart health within our school community, along with hosting guest speakers when possible. We are partnered with the American Heart Association.', 'A205', 'First Wednesday of the month', null, true, array['CPR & life-saving skills', 'Heart health awareness', 'Cardiology', 'Interested in medicine and healthcare careers', 'Guest speakers', 'Community health education', 'Partnered with the American Heart Association']::text[], '{"science_stem": 1, "arts_creative": 0, "health_medical": 5, "competitiveness": 0, "performing_arts": 0, "time_commitment": 2, "world_languages": 0, "trades_technical": 0, "community_service": 4, "cultural_identity": 0, "sports_recreation": 0, "team_vs_individual": 3, "academic_competition": 0, "computer_science_tech": 0, "leadership_government": 1, "leadership_opportunity": 2, "social_special_interest": 1, "public_speaking_emphasis": 1, "writing_media_journalism": 0, "business_entrepreneurship": 0, "environmental_sustainability": 0}'::jsonb, 'wayzata_americanheart', 'wayzataamericanheart@gmail.com, clarice.jorenby@wayzataschools.org', null, '["https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/aha-american-heart-association-2.jpg", "https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/aha-american-heart-association-1.png"]'::jsonb),
  ('art-club', 'Art Club', 'Visual & Written Arts', 'Ericka Bachmeier', 'An open space to make art with other students. Meetings are planned by a student leadership board around what members want to do.', 'Students interested in visual art of any medium or skill level.', 'The WHS Art Club is a space where students with an interest in art can come together and create with like-minded people. Activities and meetings are planned by a student-led leadership board with the group''s interests in mind. We create, we laugh, we learn, we make art together.', 'D210', 'Every other Tuesday', null, false, array['A visual artist', 'Loves drawing, painting, or design', 'Creative', 'Enjoys hands-on projects', 'Interested in art or design careers', 'Values self-expression']::text[], '{"science_stem": 0, "arts_creative": 5, "health_medical": 0, "competitiveness": 0, "performing_arts": 0, "time_commitment": 1, "world_languages": 0, "trades_technical": 0, "community_service": 0, "cultural_identity": 0, "sports_recreation": 0, "team_vs_individual": 2, "academic_competition": 0, "computer_science_tech": 0, "leadership_government": 0, "leadership_opportunity": 1, "social_special_interest": 2, "public_speaking_emphasis": 0, "writing_media_journalism": 0, "business_entrepreneurship": 0, "environmental_sustainability": 0}'::jsonb, 'wayzata.art.club', 'ericka.bachmeier@wayzataschools.org', null, '["https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/art-club-1.png", "https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/art-club-2.png"]'::jsonb),
  ('band', 'Band', 'Performance Arts', 'Dave Elmhirst, Don Krubsack, Dan Tewalt', 'A curricular program and one of the largest high school band programs in the state, with about 400 students taking part every year. Students join by enrolling in a band class or auditioning for an ensemble.', 'Instrumentalists of any experience level. Participation runs through enrolling in a music class rather than signing up for a club.', 'Band is a curricular program at Wayzata and one of the largest high school band programs in the state, with about 400 students taking part every year. There are two ways in: enroll in a band class, or audition for an ensemble. Season length, rehearsal schedules and meeting times all vary by group. Most ensembles perform about four concerts a year, and some also play at athletic events.

Students interested in joining band, choir, or orchestra should contact the appropriate teacher for more information. If you are unsure who to contact, you can ask any music teacher or your counselor for the appropriate contact information. For students not enrolled in band, choir, or orchestra, limited opportunities to participate in our co-curricular music groups will be communicated through the student newsletter.', null, null, null, false, array['Plays a wind, brass, or percussion instrument', 'Enjoys music', 'Likes performing and working in an ensemble', 'Disciplined', 'Full of school spirit, especially for marching', 'Enjoys a social music community', 'Plays trumpet, flute, clarinet, saxophone, tuba, drums or percussion', 'Marching band', 'Jazz band', 'Concert band', 'Instrumental music', 'Performing on stage']::text[], '{"science_stem": 0, "arts_creative": 2, "health_medical": 0, "competitiveness": 2, "performing_arts": 5, "time_commitment": 4, "world_languages": 0, "trades_technical": 0, "community_service": 0, "cultural_identity": 0, "sports_recreation": 0, "team_vs_individual": 5, "academic_competition": 0, "computer_science_tech": 0, "leadership_government": 0, "leadership_opportunity": 1, "social_special_interest": 2, "public_speaking_emphasis": 0, "writing_media_journalism": 0, "business_entrepreneurship": 0, "environmental_sustainability": 0}'::jsonb, 'wayzatabands', 'daniel.tewalt@wayzataschools.org', null, '["https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/band-1.png", "https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/band-2.png"]'::jsonb),
  ('beads-of-serenity', 'Beads of Serenity', 'Service & Leadership', 'Micah Schaefer', 'Student-led club making beaded bracelets once a month and donating them to memory care residents, hospital patients and other community organizations. All supplies provided.', 'Students who want a low-commitment way to do something kind — no crafting experience or supplies needed.', 'Beads of Serenity is a student-led club that focuses on giving back to the community through creating and donating bracelets. The goal of giving these bracelets is to spread kindness and care, give back to the community, raise awareness, and form connections.

Every bracelet is student-made during the club’s once-a-month morning meetings, using string and beads that the club board supplies for members to use, so there is nothing to bring and no crafting experience needed. Finished bracelets are donated to organizations and facilities around the area, including Parks Place Memory Care Facility and the children’s hospital.

The club is open to all students throughout the year, and information and updates are posted on the club Instagram.', 'Micah Schaefer’s classroom', 'One Tuesday a month', 'Before school, 7:30 a.m.', true, array['Making bracelets', 'Crafting', 'Community service', 'Spreading kindness', 'Donating to hospitals', 'Memory care residents', 'Small hands-on projects', 'Low time commitment', 'Beginner friendly', 'Supplies provided']::text[], '{"science_stem": 0, "arts_creative": 5, "health_medical": 1, "competitiveness": 0, "performing_arts": 0, "time_commitment": 1, "world_languages": 0, "trades_technical": 0, "community_service": 5, "cultural_identity": 0, "sports_recreation": 0, "team_vs_individual": 3, "academic_competition": 0, "computer_science_tech": 0, "leadership_government": 0, "leadership_opportunity": 1, "social_special_interest": 2, "public_speaking_emphasis": 0, "writing_media_journalism": 0, "business_entrepreneurship": 0, "environmental_sustainability": 0}'::jsonb, 'whsbeadsofserenity', 'richajan001@isd284.com', null, '["https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/beads-of-serenity-1.png", "https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/beads-of-serenity-2.png"]'::jsonb),
  ('biology-club', 'Biology Club', 'Academic Competition', 'Dan Dobson', 'Explores biology beyond the classroom; often preps for competitions like the USA Biology Olympiad or does labs/dissections and guest talks.', 'Students curious about biology/life sciences who want hands-on lab experience or want to compete academically in the subject.', 'Biology Club goes beyond the classroom curriculum with hands-on labs, dissections, and talks from guest speakers in life-science fields. Many members prepare for national competitions like the USA Biology Olympiad, making it a strong fit for students who want a deeper, more independent dive into biology than regular coursework allows.', null, null, null, false, array['Future doctors, nurses, or veterinarians', 'Pre-med students', 'Wildlife and nature lovers', 'Interested in environmental science', 'Enjoys labs and dissections', 'Curious about the human body and genetics', 'Likes hands-on science']::text[], '{"science_stem": 5, "arts_creative": 0, "health_medical": 3, "competitiveness": 3, "performing_arts": 0, "time_commitment": 3, "world_languages": 0, "trades_technical": 0, "community_service": 0, "cultural_identity": 0, "sports_recreation": 0, "team_vs_individual": 2, "academic_competition": 4, "computer_science_tech": 0, "leadership_government": 0, "leadership_opportunity": 1, "social_special_interest": 1, "public_speaking_emphasis": 1, "writing_media_journalism": 0, "business_entrepreneurship": 0, "environmental_sustainability": 1}'::jsonb, 'wayzatabiologyclub', null, null, '["https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/Biology.jpg", "https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/Biology%202.jpg"]'::jsonb),
  ('business-professionals-of-america', 'Business Professionals of America (BPA)', 'Academic Competition', 'Michelle Jacklitch, Tika Kude', 'Business Professionals of America prepares students for the business workforce by building leadership, professionalism, and competency. BPA is a student organization that promotes leadership and success in business. We prepare students for the global workforce through competition and community.', 'Students interested in business, office/IT skills, or finance careers.', 'Business Professionals of America prepares students for the business workforce by building leadership, professionalism, and competency. BPA is a student organization that promotes leadership and success in business. We prepare students for the global workforce through competition and community. BPA is a Career and Technical Student Organization covering business, information technology, office administration, and finance, with technical and leadership competitive events. An informational meeting is held September 22nd in the 2nd floor forum.', null, null, null, false, array['Interested in business, IT, or finance', 'Likes office and administration skills', 'Entrepreneurial', 'Enjoys structured competition', 'Wants to build a resume', 'Has corporate or professional career goals']::text[], '{"science_stem": 0, "arts_creative": 0, "health_medical": 0, "competitiveness": 4, "performing_arts": 0, "time_commitment": 3, "world_languages": 0, "trades_technical": 0, "community_service": 0, "cultural_identity": 0, "sports_recreation": 0, "team_vs_individual": 3, "academic_competition": 4, "computer_science_tech": 3, "leadership_government": 2, "leadership_opportunity": 3, "social_special_interest": 0, "public_speaking_emphasis": 2, "writing_media_journalism": 1, "business_entrepreneurship": 5, "environmental_sustainability": 0}'::jsonb, 'wayzatabpa', 'whsbpa@wayzataschools.org, tika.kude@wayzataschools.org, michelle.jacklitch@wayzataschools.org', null, '["https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/business-professionals-of-america-1.png", "https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/business-professionals-of-america-2.png"]'::jsonb),
  ('chess-club', 'Chess Club', 'Academic Competition', 'James Titus', 'Inviting everyone to participate in our Wayzata High School Chess Club. We meet at the Media Center every Friday, starting October 2nd, 2026 until April 2027. Chess Club members will have the opportunity to participate in multiple tournaments throughout the season. Students are prepared to participate in the State Scholastic Championship, which is held in March 2027. There is opportunity for Chess Club members to become leaders of the Chess Club.', 'Anyone who enjoys chess, from beginners to tournament-level players.', 'Inviting everyone to participate in our Wayzata High School Chess Club. We meet at the Media Center every Friday, starting October 2nd, 2026 until April 2027. Chess Club members will have the opportunity to participate in multiple tournaments throughout the season. Students are prepared to participate in the State Scholastic Championship, which is held in March 2027. There is opportunity for Chess Club members to become leaders of the Chess Club.', 'Media Center', 'Fridays', '3:30-5:00 p.m.', false, array['Strategic thinkers', 'Enjoys logic puzzles', 'Wants competition without physical activity', 'Math-minded', 'Patient', 'Likes one-on-one competition', 'Planning-oriented', 'Good fit for introverts']::text[], '{"science_stem": 1, "arts_creative": 0, "health_medical": 0, "competitiveness": 3, "performing_arts": 0, "time_commitment": 1, "world_languages": 0, "trades_technical": 0, "community_service": 0, "cultural_identity": 0, "sports_recreation": 0, "team_vs_individual": 2, "academic_competition": 3, "computer_science_tech": 0, "leadership_government": 0, "leadership_opportunity": 1, "social_special_interest": 3, "public_speaking_emphasis": 0, "writing_media_journalism": 0, "business_entrepreneurship": 0, "environmental_sustainability": 0}'::jsonb, 'wayzatachessclub', 'james.titus@wayzataschools.org', null, '["https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/Chess.jpg", "https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/Chess%202.jpg"]'::jsonb),
  ('chinese-club', 'Chinese Club', 'Language & Culture', 'Meng Tisdell', 'After-school activities exploring Chinese language and culture, from traditional holidays to arts and cultural celebrations. No language skills required.', 'Anyone curious about Chinese language or culture — no language experience required.', 'Wayzata High School Chinese Club provides after-school activities designed to promote and encourage students to learn about Chinese language and culture. No language skills are required — everyone is welcome to join.

The club has previously organized activities connected to Chinese culture, including traditional holidays, arts and cultural celebrations. The club has student officers, who are elected by the members.', 'A111', 'Every other Tuesday, all year', 'After school, 3:20-4:20 p.m.', false, array['Interested in Chinese language and culture', 'No language experience needed', 'Beginner friendly', 'Chinese holidays and festivals', 'Arts and cultural celebrations', 'Likes learning languages', 'Curious about Asia', 'Enjoys cultural exchange', 'Interested in international business or travel']::text[], '{"science_stem": 0, "arts_creative": 2, "health_medical": 0, "competitiveness": 0, "performing_arts": 0, "time_commitment": 2, "world_languages": 5, "trades_technical": 0, "community_service": 0, "cultural_identity": 4, "sports_recreation": 0, "team_vs_individual": 3, "academic_competition": 0, "computer_science_tech": 0, "leadership_government": 0, "leadership_opportunity": 1, "social_special_interest": 2, "public_speaking_emphasis": 1, "writing_media_journalism": 0, "business_entrepreneurship": 0, "environmental_sustainability": 0}'::jsonb, 'whs_chinese', null, null, '["https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/chinese-club-1.png", "https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/chinese-club-2.png", "https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/chinese-club-3.jpg"]'::jsonb),
  ('choirs', 'Choirs', 'Performance Arts', 'Eliza Lewis-O''Connor, Elijah Leer', 'A curricular program offering multiple vocal ensembles that range in style and skill level. Students join by enrolling in a choir class.', 'Students who want to sing, at a range of experience levels. Participation runs through enrolling in a music class rather than signing up for a club.', 'Choirs is a curricular program at Wayzata offering multiple vocal ensembles for students who want to sing, ranging in style and skill level. Students join by enrolling in a choir class.

Students interested in joining band, choir, or orchestra should contact the appropriate teacher for more information. If you are unsure who to contact, you can ask any music teacher or your counselor for the appropriate contact information. For students not enrolled in band, choir, or orchestra, limited opportunities to participate in our co-curricular music groups will be communicated through the student newsletter.', null, null, null, false, array['Enjoys singing', 'Loves music', 'A performer', 'Likes group harmony', 'Expressive', 'Wants a vocal outlet', 'Choir', 'Vocal music', 'A singer', 'Performing on stage']::text[], '{"science_stem": 0, "arts_creative": 2, "health_medical": 0, "competitiveness": 1, "performing_arts": 5, "time_commitment": 4, "world_languages": 0, "trades_technical": 0, "community_service": 0, "cultural_identity": 0, "sports_recreation": 0, "team_vs_individual": 5, "academic_competition": 0, "computer_science_tech": 0, "leadership_government": 0, "leadership_opportunity": 1, "social_special_interest": 2, "public_speaking_emphasis": 0, "writing_media_journalism": 0, "business_entrepreneurship": 0, "environmental_sustainability": 0}'::jsonb, 'wayzata_choirs', 'eliza.lewisoconnor@wayzataschools.org', null, '["https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/choirs-1.png", "https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/choirs-2.png"]'::jsonb),
  ('club-unified-students', 'Club Unified Students', 'Service & Leadership', 'Kelsey Coley', 'Students who have an interest in developing meaningful relationships between students with and without disabilities, help spread acceptance and ensure everyone feels included and welcome in their school, along with having an interest in creating authentic inclusion activities inside and outside of school that change how students interact with one another on a daily basis. Club Unified, also known as Club US, is an extracurricular activity that participates in activities such as bowling outings, cornhole tournaments, arts and craft events, the Polar Plunge at Lake Nokomis, SOMN Student Engagement Events, apple orchards, and many more. Club Unified is led, planned, and initiated by our student club members at Wayzata High School.', 'Students who want to support peers with and without disabilities.', 'Students who have an interest in developing meaningful relationships between students with and without disabilities, help spread acceptance and ensure everyone feels included and welcome in their school, along with having an interest in creating authentic inclusion activities inside and outside of school that change how students interact with one another on a daily basis. Club Unified, also known as Club US, is an extracurricular activity that participates in activities such as bowling outings, cornhole tournaments, arts and craft events, the Polar Plunge at Lake Nokomis, SOMN Student Engagement Events, apple orchards, and many more. Club Unified is led, planned, and initiated by our student club members at Wayzata High School.', 'H125 (The room right next to the weight room)', 'Once a month either on Tuesday or Thursdays', 'Before school, 7:40-8:10 a.m.', false, array['Inclusive and compassionate', 'Interested in disability advocacy', 'Enjoys working with peers of all abilities', 'Service-minded', 'Patient and friendly', 'Interested in special education, therapy, or social work']::text[], '{"science_stem": 0, "arts_creative": 0, "health_medical": 1, "competitiveness": 0, "performing_arts": 0, "time_commitment": 2, "world_languages": 0, "trades_technical": 0, "community_service": 4, "cultural_identity": 1, "sports_recreation": 2, "team_vs_individual": 5, "academic_competition": 0, "computer_science_tech": 0, "leadership_government": 1, "leadership_opportunity": 2, "social_special_interest": 4, "public_speaking_emphasis": 0, "writing_media_journalism": 0, "business_entrepreneurship": 0, "environmental_sustainability": 0}'::jsonb, 'wayzatasclubunified', 'roberels000@isd284.com, kelsey.coley@wayzataschools.org', null, '["https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/club-unified-students-1.png", "https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/club-unified-students-2.png"]'::jsonb),
  ('club-utsaav', 'Utsaav: South Asian Student Group', 'Language & Culture', 'Jahnavi Tripuraneni', 'We are a cultural group for South Asian students. We have monthly projects tied to making an impact in our Wayzata community as well as the South Asian one. For example, in the past we have run food drives during Diwali as well as collaborated with other groups like Wayzata Neuroscience and Wayzata Care Crafts to make cards for hospital patients. We have also partnered with South Asian Associations to provide students with volunteer opportunities as well as discounts.', 'Students interested in Indian culture and community service.', 'We are a cultural group for South Asian students. We have monthly projects tied to making an impact in our Wayzata community as well as the South Asian one. For example, in the past we have run food drives during Diwali as well as collaborated with other groups like Wayzata Neuroscience and Wayzata Care Crafts to make cards for hospital patients. We have also partnered with South Asian Associations to provide students with volunteer opportunities as well as discounts.', '2nd floor forum room', 'Second Tuesday of each month', 'After school, 3:10-4:10 p.m.', true, array['Indian culture', 'Community service', 'Cultural connection', 'Community impact']::text[], '{"science_stem": 0, "arts_creative": 0, "health_medical": 0, "competitiveness": 0, "performing_arts": 0, "time_commitment": 1, "world_languages": 0, "trades_technical": 0, "community_service": 3, "cultural_identity": 5, "sports_recreation": 0, "team_vs_individual": 3, "academic_competition": 0, "computer_science_tech": 0, "leadership_government": 0, "leadership_opportunity": 1, "social_special_interest": 1, "public_speaking_emphasis": 0, "writing_media_journalism": 0, "business_entrepreneurship": 0, "environmental_sustainability": 0}'::jsonb, 'wayzatautsaav', 'rishika2728@gmail.com', null, '["https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/club-utsaav-1.png", "https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/club-utsaav-2.png"]'::jsonb),
  ('crafted-with-care', 'Crafted With Care', 'Service & Leadership', 'Mr. Drogemueller', 'Handmade crafts and projects for nursing home residents, made once a month by students.', 'Students who like making things and want their crafting to go somewhere meaningful.', 'Crafted With Care is a student group at Wayzata High School that brings creativity and kindness together. Once a month, members meet to make handmade crafts and thoughtful projects for residents of nursing homes. Our goal is to create meaningful items that can brighten someone''s day and help residents feel remembered and cared for.', 'A313', 'Second Thursday of the month', 'Before school, 7:40-8:10 a.m.', true, array['Crafts', 'Nursing homes', 'Community service', 'Handmade crafts for nursing home residents', 'Crafting', 'Monthly service project']::text[], '{"science_stem": 0, "arts_creative": 5, "health_medical": 0, "competitiveness": 0, "performing_arts": 0, "time_commitment": 2, "world_languages": 0, "trades_technical": 0, "community_service": 5, "cultural_identity": 0, "sports_recreation": 0, "team_vs_individual": 3, "academic_competition": 0, "computer_science_tech": 0, "leadership_government": 0, "leadership_opportunity": 1, "social_special_interest": 2, "public_speaking_emphasis": 0, "writing_media_journalism": 0, "business_entrepreneurship": 0, "environmental_sustainability": 0}'::jsonb, 'craftedwithcare.whs', 'shola.adekola28@gmail.com', null, '["https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/crafted-with-care-1.png", "https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/crafted-with-care-2.png"]'::jsonb),
  ('creative-writing-club', 'Creative Writing Club / The Voice Literary Magazine', 'Visual & Written Arts', 'Colleen Regnier', 'A creative community for writers of every kind. Workshops, monthly themes, contests, readings with local authors, and the school''s literary magazine.', 'Students who write anything at all, from poetry to screenplays to novels, at any level of experience, and any student who wants to publish work in the literary magazine.', 'Creative Writing Club calls all writers, poets, world builders, screenwriters, playwrights and lyricists. As a creative community, we publish the school''s literary magazine, host events with monthly themes, and take part in contests and publication opportunities. We give constructive feedback and host workshops and readings with local authors. We are open to all kinds of work and all kinds of goals. Come visit the glass case of published works by CWC authors on the 2nd floor of C Wing.

The club publishes The Voice, the school''s online literary magazine, twice a year, featuring student art, poetry, short stories and novel chapters. Entries are accepted throughout the year, and any student may submit work whether or not they attend meetings.', 'C221', 'Every Thursday', '3:20-4:20 p.m.', false, array['Enjoys writing poetry and fiction', 'Creative', 'Expressive', 'Likes publishing and sharing their work', 'Interested in becoming a writer or editor', 'Reflective and introspective']::text[], '{"science_stem": 0, "arts_creative": 4, "health_medical": 0, "competitiveness": 0, "performing_arts": 0, "time_commitment": 2, "world_languages": 0, "trades_technical": 0, "community_service": 0, "cultural_identity": 0, "sports_recreation": 0, "team_vs_individual": 2, "academic_competition": 0, "computer_science_tech": 0, "leadership_government": 0, "leadership_opportunity": 1, "social_special_interest": 1, "public_speaking_emphasis": 0, "writing_media_journalism": 5, "business_entrepreneurship": 0, "environmental_sustainability": 0}'::jsonb, 'wayzatacreativewriting', 'cwc.whs@gmail.com, colleen.regnier@wayzataschools.org', null, '["https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/creative-writing-club-the-voice-literary-magazine-1.png", "https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/creative-writing-club-the-voice-literary-magazine-2.png"]'::jsonb),
  ('crochet-group', 'Crochet Group', 'Visual & Written Arts', 'Clark Doten', 'Wayzata Crochet Club strives to create a fun, low-stress, and creative environment for aspiring and expert crocheters. We welcome crocheters at all levels, whether you''re just starting or already advanced. We will also learn the basics of how to crochet together, and you''ll create small projects to enjoy or share with friends and family.', 'Crocheters at every level, from complete beginners to advanced.', 'Wayzata Crochet Club strives to create a fun, low-stress, and creative environment for aspiring and expert crocheters. We welcome crocheters at all levels, whether you''re just starting or already advanced. We will also learn the basics of how to crochet together, and you''ll create small projects to enjoy or share with friends and family.', 'C406', 'Every other Friday', 'After school, 3:10-4:10 p.m.', true, array['Crochet', 'Learning to crochet', 'All skill levels welcome', 'Low-stress creative environment', 'Small projects to keep or gift', 'Knitting and yarn crafts']::text[], '{"science_stem": 0, "arts_creative": 5, "health_medical": 0, "competitiveness": 0, "performing_arts": 0, "time_commitment": 1, "world_languages": 0, "trades_technical": 0, "community_service": 0, "cultural_identity": 0, "sports_recreation": 0, "team_vs_individual": 2, "academic_competition": 0, "computer_science_tech": 0, "leadership_government": 0, "leadership_opportunity": 1, "social_special_interest": 3, "public_speaking_emphasis": 0, "writing_media_journalism": 0, "business_entrepreneurship": 0, "environmental_sustainability": 0}'::jsonb, 'wayzatacrochet', 'wayzatacrochetclub@gmail.com, clark.doten@wayzataschools.org', null, '["https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/crochet-group-1.png", "https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/crochet-group-2.png"]'::jsonb),
  ('dance-club', 'Showstoppers', 'Performance Arts', 'Olivia Conn', 'Showstoppers is Wayzata''s dance group: members choreograph together, explore new styles and perform through the year. Membership is by tryout — tryouts for the Showstoppers take place in the Spring for the following school year.', 'Students with dance experience who want to choreograph and perform, and who can try out in the spring for the following school year.', 'Showstoppers is Wayzata''s dance group, for students who want to keep dancing outside of a studio setting. Members work on choreography together, explore different styles, and build routines as a group over the course of the year. A lot of what the group does is shaped by the people in it, so members have real say in what gets worked on from one season to the next. Membership is not open sign-up: tryouts for the Showstoppers take place in the Spring for the following school year.', null, null, null, false, array['Enjoys dance and movement', 'A performer', 'Expressive', 'Likes choreography', 'Blends athletic and artistic sides', 'Enjoys teamwork', 'A dancer', 'Dancing', 'Performing on stage']::text[], '{"science_stem": 0, "arts_creative": 2, "health_medical": 1, "competitiveness": 1, "performing_arts": 5, "time_commitment": 3, "world_languages": 0, "trades_technical": 0, "community_service": 0, "cultural_identity": 1, "sports_recreation": 2, "team_vs_individual": 4, "academic_competition": 0, "computer_science_tech": 0, "leadership_government": 0, "leadership_opportunity": 1, "social_special_interest": 2, "public_speaking_emphasis": 0, "writing_media_journalism": 0, "business_entrepreneurship": 0, "environmental_sustainability": 0}'::jsonb, null, null, null, '["https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/dance-club-1.jpg"]'::jsonb),
  ('data-science-and-ai', 'Data Science & AI', 'CTE', 'Pegge Fox', 'Explores machine learning, data analysis and real-world AI applications through hands-on projects, competitions and guest speakers.', 'Students who want to work with data and AI hands-on rather than just read about them.', 'Data Science & AI is a student-led group for students who want to work with data and artificial intelligence directly rather than just read about them.

Members explore machine learning, data analysis and real-world applications of AI through hands-on projects. The group also enters competitions and brings in guest speakers, so members can see how data science is used outside of school. Sessions are project-based, which means members pick up the tools by building something with them.', 'Ms. Fox''s room', 'Every other Wednesday', 'After school, 3:10-4:10 p.m.', true, array['Machine learning', 'Data analysis', 'Real-world AI applications', 'Hands-on projects', 'Building models', 'Competitions', 'Guest speakers', 'Tech careers']::text[], '{"science_stem": 3, "arts_creative": 0, "health_medical": 0, "competitiveness": 2, "performing_arts": 0, "time_commitment": 2, "world_languages": 0, "trades_technical": 0, "community_service": 0, "cultural_identity": 0, "sports_recreation": 0, "team_vs_individual": 4, "academic_competition": 2, "computer_science_tech": 5, "leadership_government": 0, "leadership_opportunity": 1, "social_special_interest": 1, "public_speaking_emphasis": 0, "writing_media_journalism": 0, "business_entrepreneurship": 0, "environmental_sustainability": 0}'::jsonb, null, 'whsaidatascience@gmail.com', null, '["https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/data-science-and-ai-1.jpg"]'::jsonb),
  ('debate', 'Debate', 'Academic Competition', 'Cody Dorumsgaard', 'Formal argumentation in formats like Lincoln-Douglas, Public Forum, or Policy. Research-heavy, competes at MSHSL tournaments.', 'Students who enjoy research, argumentation, and public speaking under pressure.', 'Debate is a research-heavy competitive speech activity where students argue assigned resolutions in formats like Lincoln-Douglas (one-on-one value debate), Public Forum (team-based current-events debate), and Policy (evidence-intensive team debate). Members compete at MSHSL-sanctioned tournaments throughout the season.', null, null, null, false, array['Future lawyers or politicians', 'Strong public speakers', 'Enjoys arguing and persuading', 'Follows current events closely', 'Research-oriented', 'Quick thinkers', 'Wants a competitive academic outlet', 'Confident presenters']::text[], '{"science_stem": 0, "arts_creative": 0, "health_medical": 0, "competitiveness": 5, "performing_arts": 0, "time_commitment": 4, "world_languages": 0, "trades_technical": 0, "community_service": 0, "cultural_identity": 0, "sports_recreation": 0, "team_vs_individual": 3, "academic_competition": 5, "computer_science_tech": 0, "leadership_government": 2, "leadership_opportunity": 2, "social_special_interest": 1, "public_speaking_emphasis": 5, "writing_media_journalism": 3, "business_entrepreneurship": 1, "environmental_sustainability": 0}'::jsonb, 'wayzata_debate', null, null, '["https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/debate-1.png", "https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/debate-2.png"]'::jsonb),
  ('deca', 'DECA', 'Academic Competition', 'Michelle Jacklitch, Paul Kimbler', 'A student-led business and leadership organization with about 300 members, exploring careers in business, entrepreneurship, marketing, finance, hospitality and management through competition.', 'Students interested in business, marketing, entrepreneurship or finance. Leans more toward marketing and entrepreneurship than BPA does, which is stronger on office and IT skills.', 'Wayzata DECA is a student-led business and leadership organization at Wayzata High School that gives students hands-on opportunities to explore careers in business, entrepreneurship, marketing, finance, hospitality and management. With approximately 300 members, Wayzata DECA provides students with opportunities to develop professional skills that extend beyond the classroom through competitions, workshops, leadership experiences and collaborative projects.

The only requirement is taking one business course during the school year, in any semester. Members participate in DECA competitive events, where students apply business concepts to real-world scenarios. Depending on their first event, students may complete written business projects, develop marketing or entrepreneurship plans, or create presentations. Members'' second event includes a role-play scenario where they solve a business problem in front of a judge. Members prepare through practice sessions, workshops, mock competitions and individualized feedback before competing at the district, state and international levels. Successful members have the opportunity to advance to DECA''s International Career Development Conference (ICDC), where they compete against students from across the country and around the world. This year ICDC will take place in Anaheim, California.

Beyond competition, Wayzata DECA focuses heavily on professional development and leadership. Members learn skills such as public speaking, teamwork, problem-solving, communication, networking, research, presentation design and time management. The chapter also offers DECAchieve, an after-school program where members can get additional support with event preparation and meet business professionals who help them succeed in competition.

Wayzata DECA also provides opportunities for students to take on leadership roles and contribute to the broader community. Members can help organize chapter events, lead workshops, mentor other students, take part in fundraising and service initiatives, and develop programs that introduce younger students to business and entrepreneurship. They also host the best socials.', 'Forum rooms', 'Monthly, with a morning and an evening session each month', null, false, array['Future marketers or entrepreneurs', 'Interested in business or finance majors', 'Likes hospitality and tourism', 'Sales-minded', 'Enjoys role-play case competitions', 'Confident presenter', 'Blends creativity with business sense']::text[], '{"science_stem": 0, "arts_creative": 1, "health_medical": 0, "competitiveness": 5, "performing_arts": 0, "time_commitment": 3, "world_languages": 0, "trades_technical": 0, "community_service": 0, "cultural_identity": 0, "sports_recreation": 0, "team_vs_individual": 3, "academic_competition": 4, "computer_science_tech": 1, "leadership_government": 2, "leadership_opportunity": 3, "social_special_interest": 0, "public_speaking_emphasis": 4, "writing_media_journalism": 1, "business_entrepreneurship": 5, "environmental_sustainability": 0}'::jsonb, 'wayzatadeca', 'wayzata.deca@gmail.com, paul.kimbler@wayzataschools.org, michelle.jacklitch@wayzataschools.org', null, '["https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/deca-1.png", "https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/deca-2.png"]'::jsonb),
  ('drama-club-and-theatre', 'Drama Club and Theatre', 'Performance Arts', 'Justin Spooner', 'The WHS Drama Club offers students a vibrant gateway to explore all aspects of theatre, both onstage and off. Members produce six performances annually, participate in exciting social events and workshops, and connect with peers who share their passion for the performing arts.', 'Students interested in acting, directing, or technical theater production.', 'The WHS Drama Club offers students a vibrant gateway to explore all aspects of theatre, both onstage and off. Members produce six performances annually, participate in exciting social events and workshops, and connect with peers who share their passion for the performing arts.', null, null, null, false, array['An actor', 'Enjoys performing', 'Also fits students who like backstage tech such as lighting, sets, and costumes', 'Six productions a year', 'Workshops and social events', 'Creative', 'Collaborative', 'Expressive', 'A storyteller', 'Theater and theatre', 'Musical theater', 'Acting on stage', 'Plays and productions']::text[], '{"science_stem": 0, "arts_creative": 3, "health_medical": 0, "competitiveness": 2, "performing_arts": 5, "time_commitment": 5, "world_languages": 0, "trades_technical": 1, "community_service": 0, "cultural_identity": 0, "sports_recreation": 0, "team_vs_individual": 5, "academic_competition": 0, "computer_science_tech": 1, "leadership_government": 0, "leadership_opportunity": 2, "social_special_interest": 3, "public_speaking_emphasis": 3, "writing_media_journalism": 1, "business_entrepreneurship": 0, "environmental_sustainability": 0}'::jsonb, 'whs.theatre', 'justin.spooner@wayzataschools.org', null, '["https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/drama-club-and-theatre-1.png", "https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/drama-club-and-theatre-2.png"]'::jsonb),
  ('earthrise', 'Earthrise', 'Service & Leadership', 'Michael Shaw', 'This group is made to advocate for climate change and spread awareness. We do presentations explaining the impact of climate change worldwide and what we can do to make a change. We also offer volunteer opportunities at local parks to help pick up trash etc.', 'Students interested in environmental activism.', 'Earthrise is a group that advocates for climate change and spreads awareness. It delivers presentations explaining the worldwide impact of climate change and what actions can be taken to effect change. It also offers volunteer opportunities at local parks to help pick up trash.', 'A447 in new A', 'Every second Thursday of the month', 'After school, 3:10-4:10 p.m.', true, array['Climate change advocacy', 'Presentations', 'Volunteer opportunities', 'Park cleanups']::text[], '{"science_stem": 2, "arts_creative": 0, "health_medical": 0, "competitiveness": 0, "performing_arts": 0, "time_commitment": 2, "world_languages": 0, "trades_technical": 0, "community_service": 3, "cultural_identity": 0, "sports_recreation": 0, "team_vs_individual": 3, "academic_competition": 0, "computer_science_tech": 0, "leadership_government": 2, "leadership_opportunity": 3, "social_special_interest": 1, "public_speaking_emphasis": 3, "writing_media_journalism": 0, "business_entrepreneurship": 0, "environmental_sustainability": 5}'::jsonb, 'earthrise.whs', 'abhyankaraarya6@gmail.com', null, '["https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/earthrise-1.png", "https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/earthrise-2.png"]'::jsonb),
  ('educators-rising', 'Educators Rising', 'CTE', 'Laurie Sonstegard', 'A chance for students who are interested in becoming a teacher or assisting in a school! We created a club, Educators Rising, to connect students within school who have an interest in teaching in the future!', 'Students interested in becoming an educator.', 'A chance for students who are interested in becoming a teacher or assisting in a school! We created a club, Educators Rising, to connect students within school who have an interest in teaching in the future!', 'C123', 'Once or twice a month on Wednesdays', 'Before school, 7:40-8:10 a.m.', true, array['Teacher', 'Counselor', 'Principal', 'Educator']::text[], '{"science_stem": 0, "arts_creative": 0, "health_medical": 0, "competitiveness": 0, "performing_arts": 0, "time_commitment": 1, "world_languages": 0, "trades_technical": 0, "community_service": 4, "cultural_identity": 0, "sports_recreation": 0, "team_vs_individual": 3, "academic_competition": 0, "computer_science_tech": 0, "leadership_government": 1, "leadership_opportunity": 2, "social_special_interest": 3, "public_speaking_emphasis": 0, "writing_media_journalism": 0, "business_entrepreneurship": 0, "environmental_sustainability": 0}'::jsonb, 'educators.rising.whs', 'paigevedwards@icloud.com, laurie.sonstegard@wayzataschools.org', null, '["https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/educators-rising-1.png", "https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/educators-rising-2.png"]'::jsonb),
  ('environmental-group', 'Environmental Group', 'Service & Leadership', 'Elyssa McIntyre', 'Educational group to learn about the environment together and participate in sustainable/conservation activities.', 'Students interested in the environment and conservation.', 'Environmental Group is an educational group where students learn about the environment together and take part in sustainability and conservation activities.', 'A417', 'Before or after school on Wednesdays, 1-2 times a month', 'Before school, 7:40-8:10 a.m.', true, array['Environmental education', 'Sustainability', 'Conservation activities', 'Hands-on learning']::text[], '{"science_stem": 2, "arts_creative": 0, "health_medical": 0, "competitiveness": 0, "performing_arts": 0, "time_commitment": 1, "world_languages": 0, "trades_technical": 0, "community_service": 3, "cultural_identity": 0, "sports_recreation": 0, "team_vs_individual": 3, "academic_competition": 0, "computer_science_tech": 0, "leadership_government": 0, "leadership_opportunity": 1, "social_special_interest": 2, "public_speaking_emphasis": 0, "writing_media_journalism": 0, "business_entrepreneurship": 0, "environmental_sustainability": 5}'::jsonb, null, 'ostraoli000@isd284.com', null, '["https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/environmental-group-1.png"]'::jsonb),
  ('esports', 'Esports', 'Sports & Recreation', 'TBD', 'Competitive organized video gaming (titles vary by season/league). Advisor listed as TBD.', 'Students who want to compete in video games at a school-sponsored, team level.', 'Esports is Wayzata''s competitive gaming team, playing organized matches against other schools with titles varying by season and league. Advisor is currently listed as TBD.', null, null, null, false, array['Competitive gamer', 'Team player', 'Interested in gaming, streaming, or tech', 'Strategic thinker', 'Wants a competitive outlet that is not traditional sports']::text[], '{"science_stem": 0, "arts_creative": 0, "health_medical": 0, "competitiveness": 4, "performing_arts": 0, "time_commitment": 3, "world_languages": 0, "trades_technical": 0, "community_service": 0, "cultural_identity": 0, "sports_recreation": 3, "team_vs_individual": 4, "academic_competition": 1, "computer_science_tech": 3, "leadership_government": 0, "leadership_opportunity": 1, "social_special_interest": 4, "public_speaking_emphasis": 0, "writing_media_journalism": 0, "business_entrepreneurship": 0, "environmental_sustainability": 0}'::jsonb, 'wayzata_esports_pathways', null, null, '["https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/esports-1.png", "https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/esports-2.png"]'::jsonb),
  ('forget-me-not-organization', 'Forget Me Not Organization', 'Service & Leadership', 'Mrs. Lindrup', 'We are an organization dedicated to spreading joy and kindness through the gift of flowers. Each month, we deliver floral arrangements to various groups of people, including patients in hospitals, veterans, the elderly, and those in need of a morale boost. Our mission is to bring smiles and a sense of care to others, ensuring they know they are appreciated and valued. Through our efforts, we hope to create moments of happiness and connection in the lives of many.', 'Students who want to help patients, veterans, the elderly, and others in need.', 'We are an organization dedicated to spreading joy and kindness through the gift of flowers. Each month, we deliver floral arrangements to various groups of people, including patients in hospitals, veterans, the elderly, and those in need of a morale boost. Our mission is to bring smiles and a sense of care to others, ensuring they know they are appreciated and valued. Through our efforts, we hope to create moments of happiness and connection in the lives of many.', 'A311', 'Once a month on Friday mornings', 'Before school, 7:40-8:10 a.m.', true, array['Flowers', 'Floral arrangements', 'Hospital patients', 'Veterans', 'Elderly', 'Morale boost']::text[], '{"science_stem": 0, "arts_creative": 3, "health_medical": 0, "competitiveness": 0, "performing_arts": 0, "time_commitment": 2, "world_languages": 0, "trades_technical": 0, "community_service": 5, "cultural_identity": 0, "sports_recreation": 0, "team_vs_individual": 3, "academic_competition": 0, "computer_science_tech": 0, "leadership_government": 0, "leadership_opportunity": 2, "social_special_interest": 0, "public_speaking_emphasis": 0, "writing_media_journalism": 0, "business_entrepreneurship": 0, "environmental_sustainability": 0}'::jsonb, 'forgetmenot.global', 'syowan27@icloud.com, leililindrup@wayzataschools.org', null, '["https://pqfchywvjinosvvphshy.supabase.co/stor