  ('french-club', 'French Club', 'Language & Culture', 'Carrie Berg', 'French language and culture.', 'Students learning French or interested in French culture.', 'French Club gives students a low-pressure space to practice French and take part in cultural activities and events tied to French-speaking cultures.', null, null, null, false, array['Interested in French language and culture', 'Likes learning languages', 'Loves art, food, and travel', 'Interested in travel or international topics']::text[], '{"science_stem": 0, "arts_creative": 1, "health_medical": 0, "competitiveness": 0, "performing_arts": 0, "time_commitment": 1, "world_languages": 5, "trades_technical": 0, "community_service": 0, "cultural_identity": 4, "sports_recreation": 0, "team_vs_individual": 3, "academic_competition": 0, "computer_science_tech": 0, "leadership_government": 0, "leadership_opportunity": 1, "social_special_interest": 2, "public_speaking_emphasis": 1, "writing_media_journalism": 0, "business_entrepreneurship": 0, "environmental_sustainability": 0}'::jsonb, 'frenchclub_wayzata', null, null, '["https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/french-club-1.png"]'::jsonb),
  ('future-problem-solvers', 'Future Problem-Solvers', 'Academic Competition', 'Jon Honza', 'Future Problem Solving is primarily a team writing competition. Students work together to solve problems set in the future. There are multiple rounds of competition, moving from Regionals, then State, and finally Internationals (if students can make it that far).', 'Students who like creative problem-solving, research, writing, and a bit of performance.', 'Future Problem Solving is primarily a team writing competition. Students work together to solve problems set in the future. There are multiple rounds of competition, moving from Regionals, then State, and finally Internationals (if students can make it that far).', 'C422', 'Wednesdays', 'After school', false, array['Both creative and analytical', 'Cares about global issues like climate, tech, and society', 'Enjoys brainstorming', 'Likes writing and performing', 'Works well in teams', 'Big-picture thinkers', 'Interested in policy, consulting, or social impact']::text[], '{"science_stem": 2, "arts_creative": 2, "health_medical": 0, "competitiveness": 4, "performing_arts": 0, "time_commitment": 3, "world_languages": 0, "trades_technical": 0, "community_service": 1, "cultural_identity": 0, "sports_recreation": 0, "team_vs_individual": 4, "academic_competition": 4, "computer_science_tech": 1, "leadership_government": 0, "leadership_opportunity": 2, "social_special_interest": 1, "public_speaking_emphasis": 2, "writing_media_journalism": 3, "business_entrepreneurship": 1, "environmental_sustainability": 2}'::jsonb, 'wayzatafps', 'jonathan.honza@wayzataschools.org', null, '["https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/future-problem-solvers-1.png"]'::jsonb),
