  ('hosa-future-health-professionals', 'HOSA Future Health Professionals', 'CTE', 'Clarice Jorenby', 'Welcome to Wayzata HOSA! HOSA is a global student organization that helps students explore careers in healthcare and develop leadership skills. Members can compete in events covering topics such as medical science, public health, emergency medicine, and biomedical innovation. HOSA also provides opportunities to attend conferences, meet other students interested in healthcare, and learn from professionals in the field. Through competitions, community service, and chapter activities, HOSA encourages students to build the knowledge, confidence, and skills needed for future careers in healthcare.', 'Students considering a career in healthcare or medicine.', 'Welcome to Wayzata HOSA! HOSA is a global student organization that helps students explore careers in healthcare and develop leadership skills. Members can compete in events covering topics such as medical science, public health, emergency medicine, and biomedical innovation. HOSA also provides opportunities to attend conferences, meet other students interested in healthcare, and learn from professionals in the field. Through competitions, community service, and chapter activities, HOSA encourages students to build the knowledge, confidence, and skills needed for future careers in healthcare.', '2nd floor forum', 'First Tuesday of the month', 'Morning and afternoon', false, array['Future doctors, nurses, EMTs, dentists, or therapists', 'Interested in medicine and healthcare careers', 'Competes in medical science, public health, and emergency medicine events', 'Biomedical innovation', 'Conferences and networking', 'Service-minded', 'Wants exposure to the healthcare field']::text[], '{"science_stem": 2, "arts_creative": 0, "health_medical": 5, "competitiveness": 3, "performing_arts": 0, "time_commitment": 3, "world_languages": 0, "trades_technical": 0, "community_service": 2, "cultural_identity": 0, "sports_recreation": 0, "team_vs_individual": 2, "academic_competition": 3, "computer_science_tech": 0, "leadership_government": 1, "leadership_opportunity": 3, "social_special_interest": 0, "public_speaking_emphasis": 1, "writing_media_journalism": 0, "business_entrepreneurship": 0, "environmental_sustainability": 0}'::jsonb, 'wayzatahosa', 'hosa@wayzataschools.org, clarice.jorenby@wayzataschools.org', null, '["https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/hosa-future-health-professionals-1.png", "https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/hosa-future-health-professionals-2.png"]'::jsonb),
  ('human-anatomy', 'Human Anatomy', 'CTE', 'Seth Finck', 'The Human Anatomy Student Group provides students with hands-on learning experiences in anatomy through dissections, collaborative activities, and discussions. The group seeks to promote scientific curiosity and encourage interest in medicine and healthcare careers.', 'Students interested in medicine and healthcare careers.', 'Human Anatomy is a student group that offers hands-on learning experiences in anatomy through dissections, collaborative activities, and discussions. It seeks to promote scientific curiosity and encourage interest in medicine and healthcare careers.', 'A442', 'Every other Thursday. Later in the year in order to help prep for certain events, we will switch to every Thursday', 'After school, 3:10-4:10 p.m.', true, array['Anatomy dissections', 'Collaborative activities', 'Discussions', 'Scientific curiosity', 'Medicine careers', 'Healthcare careers']::text[], '{"science_stem": 5, "arts_creative": 0, "health_medical": 5, "competitiveness": 0, "performing_arts": 0, "time_commitment": 3, "world_languages": 0, "trades_technical": 0, "community_service": 0, "cultural_identity": 0, "sports_recreation": 0, "team_vs_individual": 4, "academic_competition": 0, "computer_science_tech": 0, "leadership_government": 0, "leadership_opportunity": 2, "social_special_interest": 2, "public_speaking_emphasis": 2, "writing_media_journalism": 0, "business_entrepreneurship": 0, "environmental_sustainability": 0}'::jsonb, 'whshumananatomy', 'parneesh000@isd284.com', null, '["https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/human-anatomy-1.png", "https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/human-anatomy-2.png"]'::jsonb),
  ('jewish-student-union', 'Jewish Student Union', 'Language & Culture', 'Sarah Gohman', 'We meet bi-weekly to discuss Jewish topics, connect with the Jewish community, and enjoy our time together.', 'Students interested in Jewish topics.', 'Jewish Student Union meets bi-weekly to discuss Jewish topics, connect with the Jewish community, and enjoy their time together.', 'I don’t know the room number but Ms. Gohman’s room in 2A horseshoe', 'Every other Wednesday', 'After school, 3:10-4:10 p.m.', true, array['Jewish topics', 'Jewish community', 'Jewish culture and traditions', 'Faith community', 'Holidays and celebrations', 'A space for Jewish students']::text[], '{"science_stem": 0, "arts_creative": 0, "health_medical": 0, "competitiveness": 0, "performing_arts": 0, "time_commitment": 1, "world_languages": 0, "trades_technical": 0, "community_service": 0, "cultural_identity": 5, "sports_recreation": 0, "team_vs_individual": 5, "academic_competition": 0, "computer_science_tech": 0, "leadership_government": 0, "leadership_opportunity": 1, "social_special_interest": 2, "public_speaking_emphasis": 2, "writing_media_journalism": 0, "business_entrepreneurship": 0, "environmental_sustainability": 0}'::jsonb, null, 'matthew.binder414@icloud.com', null, '["https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/jewish-student-union-1.png"]'::jsonb),
  ('key-club', 'Key Club', 'Service & Leadership', 'Melissa Bast', 'Student led organization exemplifying leadership and service to our community (school and beyond) by providing students with accessible volunteering opportunities while supporting our local community (service projects include: DIYs, fundraising, volunteering).', 'Students interested in leadership and community service.', 'Key Club is a student-led organization exemplifying leadership and service to the community, both at school and beyond, by providing students with accessible volunteering opportunities while supporting the local community through service projects such as DIYs, fundraising, and volunteering.', null, null, null, true, array['Leadership', 'Community service', 'Volunteering', 'DIY projects', 'Fundraising']::text[], '{"science_stem": 0, "arts_creative": 0, "health_medical": 0, "competitiveness": 0, "performing_arts": 0, "time_commitment": 2, "world_languages": 0, "trades_technical": 0, "community_service": 5, "cultural_identity": 0, "sports_recreation": 0, "team_vs_individual": 3, "academic_competition": 0, "computer_science_tech": 0, "leadership_government": 2, "leadership_opportunity": 4, "social_special_interest": 1, "public_speaking_emphasis": 1, "writing_media_journalism": 0, "business_entrepreneurship": 0, "environmental_sustainability": 0}'::jsonb, 'WayzataStudentsInService', 'WayzataTrojanKeyClub@gmail.com', null, '["https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/key-club-1.png", "https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/key-club-2.png"]'::jsonb),
  ('kids-scholarship-fund', 'Kids Scholarship Fund', 'Service & Leadership', 'Mr. Brattain', 'To give underprivileged kids a scholarship for education!', 'Students who want to help underprivileged kids get scholarships.', 'Kids Scholarship Fund gives underprivileged kids a scholarship for education.', 'A302', 'First Wednesday of the month', 'After school, 3:10-4:10 p.m.', true, array['Scholarships', 'Underprivileged kids', 'Education', 'Fundraising', 'Supporting education for underprivileged children', 'Community service', 'Making an impact beyond school']::text[], '{"science_stem": 0, "arts_creative": 0, "health_medical": 0, "competitiveness": 0, "performing_arts": 0, "time_commitment": 2, "world_languages": 0, "trades_technical": 0, "community_service": 5, "cultural_identity": 0, "sports_recreation": 0, "team_vs_individual": 3, "academic_competition": 0, "computer_science_tech": 0, "leadership_government": 0, "leadership_opportunity": 2, "social_special_interest": 0, "public_speaking_emphasis": 0, "writing_media_journalism": 0, "business_entrepreneurship": 0, "environmental_sustainability": 0}'::jsonb, null, 'gargi.purama@gmail.com', null, '["https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/kids-scholarship-fund-1.png"]'::jsonb),
  ('knots-of-kindness', 'Knots of Kindness', 'Service & Leadership', 'Sarah Gohman', 'This group is a way to bring people together as a way to participate in giving back to the less fortunate. We will make tie knot blankets and donate them to shelters/hospitals. It will be a great way to meet new people, collaborate with organizations that are important to us, and learn new skills about being a leader.', 'Students interested in community service and leadership.', 'Knots of Kindness brings people together to give back to the less fortunate by making tie knot blankets and donating them to shelters and hospitals. The group also offers a chance to meet new people, collaborate with important organizations, and develop leadership skills.', 'A211', 'Last Thursday of the month', 'Before school, 7:40-8:10 a.m.', true, array['Tie knot blankets', 'Donating to shelters/hospitals', 'Meeting new people', 'Collaborating with organizations', 'Leadership skills', 'Giving back to the less fortunate']::text[], '{"science_stem": 0, "arts_creative": 5, "health_medical": 0, "competitiveness": 0, "performing_arts": 0, "time_commitment": 1, "world_languages": 0, "trades_technical": 0, "community_service": 5, "cultural_identity": 0, "sports_recreation": 0, "team_vs_individual": 4, "academic_competition": 0, "computer_science_tech": 0, "leadership_government": 0, "leadership_opportunity": 2, "social_special_interest": 2, "public_speaking_emphasis": 0, "writing_media_journalism": 0, "business_entrepreneurship": 0, "environmental_sustainability": 0}'::jsonb, 'whsknotsofkindness', 'rabinbro000@isd284.com', null, '["https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/knots-of-kindness-1.png"]'::jsonb),
  ('latino-student-union', 'Latino Student Union', 'Language & Culture', 'Brandy Castaneda', 'Latino student union is a group where students from Latino or Hispanic origins can come together to celebrate Latino/hispanic culture, learn and share experiences, and build a sense a community for all in attendance. LSU will be a welcoming place for students interested in learning and growing their connection to their culture. We will learn about Latino tradition, history, food, music, and the impact of Latinos on society and vise versa. The club will be open to all students and will provide a safe, welcoming, and comfortable environment where every student can feel seen and respected. The full purpose of LSU is to allow students to feel more connected, represented, and supported. For many students whose families come from Latin American countries, the group can be a place where they feel closer to their culture and heritage, while navigating a new environment.', 'Students interested in Latino/Hispanic culture.', 'Latino Student Union is a group where students from Latino or Hispanic origins can come together to celebrate Latino/Hispanic culture, learn and share experiences, and build a sense of community for all in attendance. The club explores Latino tradition, history, food, music, and the impact of Latinos on society and vice versa, while welcoming all students and providing a safe, welcoming, and comfortable environment where every student can feel seen and respected. Its purpose is to allow students to feel more connected, represented, and supported, and for many students whose families come from Latin American countries, it can be a place where they feel closer to their culture and heritage while navigating a new environment.', 'Ms. Brandy Office (For now)', 'Every 1st Wednesday of the month', 'After school, 3:10-4:10 p.m.', true, array['Latino/Hispanic culture', 'Tradition', 'History', 'Food', 'Music', 'Community building']::text[], '{"science_stem": 0, "arts_creative": 2, "health_medical": 0, "competitiveness": 0, "performing_arts": 0, "time_commitment": 1, "world_languages": 0, "trades_technical": 0, "community_service": 0, "cultural_identity": 5, "sports_recreation": 0, "team_vs_individual": 3, "academic_competition": 0, "computer_science_tech": 0, "leadership_government": 0, "leadership_opportunity": 1, "social_special_interest": 3, "public_speaking_emphasis": 0, "writing_media_journalism": 0, "business_entrepreneurship": 0, "environmental_sustainability": 0}'::jsonb, null, 'arvizamy000@isd284.com', null, '["https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/latino-student-union-1.png"]'::jsonb),
  ('leaders-and-lawmakers', 'Leaders and Lawmakers', 'Service & Leadership', 'Amanda Campbell', 'A space where students can practice their leadership skills in so many different ways including public speaking and digging deeper on what being a lawyer and working in the field might mean for them.', 'Students interested in leadership, public speaking, and law careers.', 'Leaders and Lawmakers is a space where students practice leadership skills in many different ways, including public speaking, and dig deeper into what being a lawyer and working in the field might mean for them.', 'A418', 'Every other Wednesday', 'After school, 3:10-4:10 p.m.', true, array['Leadership skills', 'Public speaking', 'Law careers', 'Exploring the legal field']::text[], '{"science_stem": 0, "arts_creative": 0, "health_medical": 0, "competitiveness": 0, "performing_arts": 0, "time_commitment": 2, "world_languages": 0, "trades_technical": 0, "community_service": 0, "cultural_identity": 0, "sports_recreation": 0, "team_vs_individual": 3, "academic_competition": 0, "computer_science_tech": 0, "leadership_government": 4, "leadership_opportunity": 4, "social_special_interest": 1, "public_speaking_emphasis": 5, "writing_media_journalism": 0, "business_entrepreneurship": 0, "environmental_sustainability": 0}'::jsonb, null, 'goldbsho000@isd284.com', null, '["https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/leaders-and-lawmakers-1.png"]'::jsonb),
  ('letters-of-love', 'Letters of Love', 'Service & Leadership', 'Mrs. Larson', 'We make cards for children’s hospitals once a month. They are delivered to the hospitals to bring some joy to the kids during tough times.', 'Students who want to make cards for children''s hospitals.', 'Letters of Love makes cards for children''s hospitals once a month. The cards are delivered to the hospitals to bring joy to the kids during tough times.', 'C114', 'Second Friday of every month', 'Before school, 7:40-8:10 a.m.', true, array['Cards', 'Children''s hospitals', 'Joy', 'Tough times', 'Writing letters and cards to hospitalized children', 'Sending notes to patients', 'Monthly card making', 'Community service']::text[], '{"science_stem": 0, "arts_creative": 5, "health_medical": 2, "competitiveness": 0, "performing_arts": 0, "time_commitment": 1, "world_languages": 0, "trades_technical": 0, "community_service": 5, "cultural_identity": 0, "sports_recreation": 0, "team_vs_individual": 3, "academic_competition": 0, "computer_science_tech": 0, "leadership_government": 0, "leadership_opportunity": 1, "social_special_interest": 0, "public_speaking_emphasis": 0, "writing_media_journalism": 0, "business_entrepreneurship": 0, "environmental_sustainability": 0}'::jsonb, 'whslettersoflove', 'alstebro000@isd284.com', null, '["https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/letters-of-love-1.png", "https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/letters-of-love-2.png"]'::jsonb),
  ('link-crew', 'Link Crew', 'Service & Leadership', 'Emily Haugh, Jennifer Landy', 'Trained juniors and seniors mentor incoming freshmen and new students through the transition to high school, helping them find their footing socially and academically.', 'Juniors and seniors who want a real mentoring and leadership role, and every incoming freshman on the receiving end.', 'Wayzata Link Crew is a transition and leadership program that pairs trained juniors and seniors, called Link Leaders, with incoming freshmen and new students to help them adjust to a large school environment. Link Crew is a national program used by high schools across the country, built on the idea that the students best equipped to help a freshman find their footing are the ones who did it themselves a few years earlier.

Link Leaders are trained before the school year starts and then work with a small group of freshmen, helping them navigate the move to high school both socially and academically: learning the building, understanding how classes and expectations differ from middle school, and having an older student they can go to with questions that feel too small to ask a teacher.

For upperclassmen, Link Crew is a leadership role rather than a club you drop into. It builds skills in mentoring, public speaking and working with a group, and it puts you in front of students who will remember the person who made their first weeks easier.', null, null, null, false, array['A natural mentor', 'Welcoming', 'An upperclassman who likes helping younger students', 'Interested in leadership', 'Outgoing', 'Full of school spirit', 'A good role model']::text[], '{"science_stem": 0, "arts_creative": 0, "health_medical": 0, "competitiveness": 0, "performing_arts": 0, "time_commitment": 2, "world_languages": 0, "trades_technical": 0, "community_service": 4, "cultural_identity": 0, "sports_recreation": 0, "team_vs_individual": 5, "academic_competition": 0, "computer_science_tech": 0, "leadership_government": 2, "leadership_opportunity": 4, "social_special_interest": 3, "public_speaking_emphasis": 1, "writing_media_journalism": 0, "business_entrepreneurship": 0, "environmental_sustainability": 0}'::jsonb, 'wayzata_link_crew', 'jennifer.landy@wayzataschools.org, emily.haugh@wayzataschools.org', null, '["https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/link-crew-1.png", "https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/link-crew-2.png"]'::jsonb),
  ('math-team', 'Math Team', 'Academic Competition', 'Lee Barnett', 'Competes in the Minnesota State High School Math League and contests such as the AMC. No prerequisites — every experience level finds a challenge.', 'Anyone who enjoys math and wants to test it competitively — no prerequisites, any experience level.', 'The WHS Math Team is open to any high school student who is passionate about mathematics. There are no prerequisites to joining the team, and everyone will find an enjoyable challenge regardless of experience level.

The team competes in the Minnesota State High School Math League and has access to other competitions such as the AMC. Meets are timed and mix individual problem-solving rounds with team rounds, so members work both on their own and together.', 'C314', 'Every Monday, starting October 12th', 'After school', false, array['Strong in math', 'No prerequisites', 'Beginner friendly', 'Enjoys timed problem-solving', 'Competitive', 'Likes puzzles', 'AMC', 'Interested in engineering, computer science, finance, or actuarial work', 'Thrives on precision']::text[], '{"science_stem": 4, "arts_creative": 0, "health_medical": 0, "competitiveness": 4, "performing_arts": 0, "time_commitment": 2, "world_languages": 0, "trades_technical": 0, "community_service": 0, "cultural_identity": 0, "sports_recreation": 0, "team_vs_individual": 2, "academic_competition": 5, "computer_science_tech": 1, "leadership_government": 0, "leadership_opportunity": 1, "social_special_interest": 1, "public_speaking_emphasis": 0, "writing_media_journalism": 0, "business_entrepreneurship": 0, "environmental_sustainability": 0}'::jsonb, 'wayzatamathteam', null, null, '["https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/math-team-1.png", "https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/math-team-2.png"]'::jsonb),
  ('mock-trial', 'Mock Trial', 'Academic Competition', 'Jon Honza, Tyler Trimberger', 'Simulated courtroom trials; students play attorneys and witnesses, judged on legal argument and presentation.', 'Students interested in law, public speaking, and improvisation.', 'Mock Trial recreates courtroom proceedings, with students preparing and arguing both sides of a fictional case as attorneys or playing witness roles. Teams are judged on legal reasoning, courtroom presentation, and improvisational skill, competing against other schools'' teams.', null, null, null, false, array['Future lawyers', 'Enjoys public speaking', 'Has a dramatic or theatrical streak', 'Likes debate but wants more structure', 'Detail-oriented', 'Enjoys role-play', 'Competitive', 'Good memory']::text[], '{"science_stem": 0, "arts_creative": 1, "health_medical": 0, "competitiveness": 4, "performing_arts": 0, "time_commitment": 3, "world_languages": 0, "trades_technical": 0, "community_service": 0, "cultural_identity": 0, "sports_recreation": 0, "team_vs_individual": 4, "academic_competition": 4, "computer_science_tech": 0, "leadership_government": 3, "leadership_opportunity": 2, "social_special_interest": 1, "public_speaking_emphasis": 5, "writing_media_journalism": 2, "business_entrepreneurship": 0, "environmental_sustainability": 0}'::jsonb, 'wayzatamocktrial', 'Tyler.Trimberger@wayzataschools.org, jonathan.honza@wayzataschools.org', null, '["https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/mock-trial-1.png", "https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/mock-trial-2.png"]'::jsonb),
  ('model-united-nations', 'Model United Nations', 'Academic Competition', 'Todd Larsen', 'Students role-play as country delegates, debating global issues and drafting resolutions in simulated UN committees.', 'Students interested in global affairs, diplomacy, and debate.', 'Model UN has students represent assigned countries in simulated United Nations committees, debating real global issues, negotiating with other delegates, and drafting formal resolutions. It''s a mix of research, diplomacy, and public speaking.', null, null, null, false, array['Interested in international relations and diplomacy', 'Likes politics and history', 'Follows current events', 'Enjoys formal debate', 'Interested in foreign service, law, or policy', 'Articulate writers and speakers']::text[], '{"science_stem": 0, "arts_creative": 0, "health_medical": 0, "competitiveness": 3, "performing_arts": 0, "time_commitment": 3, "world_languages": 1, "trades_technical": 0, "community_service": 1, "cultural_identity": 2, "sports_recreation": 0, "team_vs_individual": 4, "academic_competition": 4, "computer_science_tech": 0, "leadership_government": 3, "leadership_opportunity": 2, "social_special_interest": 2, "public_speaking_emphasis": 4, "writing_media_journalism": 2, "business_entrepreneurship": 0, "environmental_sustainability": 1}'::jsonb, 'wayzatamunclub', null, null, '["https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/model-united-nations-1.png", "https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/model-united-nations-2.png"]'::jsonb),
  ('muslim-student-association-msa', 'Muslim Student Association (MSA)', 'Language & Culture', 'Jamal Adam', 'As the Wayzata Muslim Student Association, it is our mission to foster a sense of unity amongst Muslims at Wayzata High School. We offer a safe space for Muslim students to explore and express their faith. Additionally, we aim to promote interfaith cooperation and awareness of Islamic culture and values. Through our discussions, debates, and informational meeting, we aim to contribute positively towards society.', 'Students interested in Muslim community and interfaith dialogue.', 'Muslim Student Association (MSA) fosters a sense of unity among Muslims at Wayzata High School. It offers a safe space for Muslim students to explore and express their faith, promotes interfaith cooperation, and raises awareness of Islamic culture and values. Through discussions, debates, and informational meetings, it aims to contribute positively to society.', 'Mainly A251 but 2nd floor forum occasionally', 'Every Tuesday', 'After school, 3:10-4:10 p.m.', true, array['Unity among Muslims', 'Safe space for faith exploration', 'Interfaith cooperation', 'Islamic culture awareness', 'Discussions and debates', 'Informational meetings']::text[], '{"science_stem": 0, "arts_creative": 0, "health_medical": 0, "competitiveness": 0, "performing_arts": 0, "time_commitment": 2, "world_languages": 0, "trades_technical": 0, "community_service": 0, "cultural_identity": 5, "sports_recreation": 0, "team_vs_individual": 4, "academic_competition": 0, "computer_science_tech": 0, "leadership_government": 0, "leadership_opportunity": 2, "social_special_interest": 2, "public_speaking_emphasis": 3, "writing_media_journalism": 0, "business_entrepreneurship": 0, "environmental_sustainability": 0}'::jsonb, 'msawayzata', 'haqzayan@gmail.com', null, '["https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/muslim-student-association-1.png", "https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/muslim-student-association-2.png"]'::jsonb),
  ('national-honor-society', 'National Honor Society', 'Service & Leadership', 'Sarah Ellis, Karin Foss', 'Recognizes academic achievement; requires service hours and upholds scholarship, leadership, service, and character.', 'High-achieving students who want to build a strong service and leadership record.', 'National Honor Society recognizes students for strong academics while requiring ongoing community service hours and involvement, built around the four pillars of scholarship, leadership, service, and character.', null, null, null, false, array['High academic achiever', 'Service-oriented', 'Interested in leadership', 'Well-rounded', 'Motivated', 'Wants recognition and a college resume boost', 'Dependable character']::text[], '{"science_stem": 0, "arts_creative": 0, "health_medical": 0, "competitiveness": 1, "performing_arts": 0, "time_commitment": 2, "world_languages": 0, "trades_technical": 0, "community_service": 4, "cultural_identity": 0, "sports_recreation": 0, "team_vs_individual": 2, "academic_competition": 1, "computer_science_tech": 0, "leadership_government": 2, "leadership_opportunity": 3, "social_special_interest": 1, "public_speaking_emphasis": 0, "writing_media_journalism": 0, "business_entrepreneurship": 0, "environmental_sustainability": 0}'::jsonb, 'wayzatanhs', 'sarah.ellis@wayzataschools.org', null, '["https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/national-honor-society-1.png", "https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/national-honor-society-2.png"]'::jsonb),
  ('nurses-of-tomorrow', 'Nurses of Tomorrow', 'CTE', 'Becky Larson (health teacher)', 'The purpose of Nurses of Tomorrow is to educate students on the vast nursing field through interactive activities, volunteering opportunities, recent news, and much more!', 'Students interested in nursing.', 'Nurses of Tomorrow educates students on the vast nursing field through interactive activities, volunteering opportunities, recent news, and much more!', 'C114 (health wing)', 'Once a month, exact date varies (usually near the end of the month)', 'After school, 3:10-4:10 p.m.', true, array['Nursing field', 'Interactive activities', 'Volunteering opportunities', 'Recent news']::text[], '{"science_stem": 0, "arts_creative": 0, "health_medical": 5, "competitiveness": 0, "performing_arts": 0, "time_commitment": 1, "world_languages": 0, "trades_technical": 0, "community_service": 2, "cultural_identity": 0, "sports_recreation": 0, "team_vs_individual": 3, "academic_competition": 0, "computer_science_tech": 0, "leadership_government": 0, "leadership_opportunity": 1, "social_special_interest": 2, "public_speaking_emphasis": 0, "writing_media_journalism": 0, "business_entrepreneurship": 0, "environmental_sustainability": 0}'::jsonb, 'wayzatanursesoftomorrow', 'abhamanoj05@gmail.com', null, '["https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/nurses-of-tomorrow-1.png", "https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/nurses-of-tomorrow-2.png"]'::jsonb),
  ('orchestras', 'Orchestras', 'Performance Arts', 'Mark Gitch, Max Clifford', 'A curricular program offering string and full-orchestra ensembles. Students join by enrolling in an orchestra class.', 'String and orchestral players who want to perform in an ensemble. Participation runs through enrolling in a music class rather than signing up for a club.', 'Orchestras is a curricular program at Wayzata offering string and full-orchestra ensembles for instrumentalists who want to perform classical and contemporary repertoire together. Students join by enrolling in an orchestra class.

Students interested in joining band, choir, or orchestra should contact the appropriate teacher for more information. If you are unsure who to contact, you can ask any music teacher or your counselor for the appropriate contact information. For students not enrolled in band, choir, or orchestra, limited opportunities to participate in our co-curricular music groups will be communicated through the student newsletter.', null, null, null, false, array['Plays a string instrument', 'Enjoys classical and ensemble music', 'Disciplined', 'Performance-minded', 'Enjoys a music community', 'Plays violin, viola, cello or double bass', 'Strings and symphony', 'Instrumental music', 'Performing on stage']::text[], '{"science_stem": 0, "arts_creative": 2, "health_medical": 0, "competitiveness": 2, "performing_arts": 5, "time_commitment": 4, "world_languages": 0, "trades_technical": 0, "community_service": 0, "cultural_identity": 0, "sports_recreation": 0, "team_vs_individual": 5, "academic_competition": 0, "computer_science_tech": 0, "leadership_government": 0, "leadership_opportunity": 1, "social_special_interest": 2, "public_speaking_emphasis": 0, "writing_media_journalism": 0, "business_entrepreneurship": 0, "environmental_sustainability": 0}'::jsonb, 'wayzataorchestra', 'mark.gitch@wayzataschools.org', null, '["https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/orchestras-1.png", "https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/orchestras-2.png"]'::jsonb),
  ('origami-for-good', 'Origami For Good', 'Service & Leadership', 'Abigail Genise', 'A youth-led nonprofit that folds origami and sends it to soldiers, seniors, hospital patients and others to spread creativity and Japanese art and culture.', 'Students who enjoy paper craft and want their creations to go somewhere meaningful.', 'Origami For Good is a youth-led 501(c)(3) nonprofit organization that makes origami and sends it to soldiers, youth, seniors, patients and more, in order to inspire creativity and appreciation for Japanese art and culture.

The Wayzata chapter meets once a month after school to fold together. Check the club’s social media and emails for important updates during the year.', 'A218', 'Second Wednesday of the month', 'After school, 3:30-4:30 p.m.', true, array['Origami', 'Paper craft', 'Japanese art & culture', 'Community service', 'Creativity', 'Giving to soldiers and hospital patients', 'Low time commitment', 'Nonprofit work']::text[], '{"science_stem": 0, "arts_creative": 5, "health_medical": 0, "competitiveness": 0, "performing_arts": 0, "time_commitment": 2, "world_languages": 0, "trades_technical": 0, "community_service": 4, "cultural_identity": 4, "sports_recreation": 0, "team_vs_individual": 3, "academic_competition": 0, "computer_science_tech": 0, "leadership_government": 0, "leadership_opportunity": 3, "social_special_interest": 2, "public_speaking_emphasis": 0, "writing_media_journalism": 0, "business_entrepreneurship": 0, "environmental_sustainability": 0}'::jsonb, 'ofg.whs', 'whs.ofg@gmail.com', null, '["https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/origami-for-good-1.png", "https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/origami-for-good-2.png"]'::jsonb),
  ('our-right-to-learn', 'Our Right to Learn', 'Service & Leadership', 'Paul Kimbler', 'Millions of children are denied access to education due to challenges such as poverty, child marriage, and child labor. Our Right to Learn works to raise awareness about these barriers and advocate for every child''s right to quality education. Education is more than classrooms and textbooks; it gives children the ability to make informed choices, uplift their communities, and build brighter futures. Through advocacy, outreach, and community engagement, we strive to support CRY America''s mission of helping children access education and reach their full potential.', 'Students who want to advocate for children''s access to education.', 'Millions of children are denied access to education due to challenges such as poverty, child marriage, and child labor. Our Right to Learn works to raise awareness about these barriers and advocate for every child''s right to quality education. Education is more than classrooms and textbooks; it gives children the ability to make informed choices, uplift their communities, and build brighter futures. Through advocacy, outreach, and community engagement, we strive to support CRY America''s mission of helping children access education and reach their full potential.', 'A145', 'Biweekly on Mondays or Wednesdays (check Instagram)', 'After school, 3:10-4:10 p.m.', true, array['CRY America', 'Fundraising', 'Awareness campaigns', 'Children''s right to education', 'Advocacy and outreach', 'Nonprofit work']::text[], '{"science_stem": 0, "arts_creative": 0, "health_medical": 0, "competitiveness": 0, "performing_arts": 0, "time_commitment": 2, "world_languages": 0, "trades_technical": 0, "community_service": 5, "cultural_identity": 0, "sports_recreation": 0, "team_vs_individual": 4, "academic_competition": 0, "computer_science_tech": 0, "leadership_government": 0, "leadership_opportunity": 3, "social_special_interest": 0, "public_speaking_emphasis": 1, "writing_media_journalism": 0, "business_entrepreneurship": 0, "environmental_sustainability": 0}'::jsonb, 'cryamerica.minnesota', 'kareenaacharya123@gmail.com, paul.kimbler@wayzataschools.org', null, '["https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/our-right-to-learn-1.png", "https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/our-right-to-learn-2.png"]'::jsonb),
  ('paws-for-a-cause', 'Paws for a Cause', 'Service & Leadership', 'Anne Hooton', 'Paws for a Cause is a motivated student group created by Lily Kramer and Abby Britz focused on helping animals in need. Our mission is to provide meaningful donations, care, and support to rescue dogs in animal shelters. Members of our club will create collars, tie-blankets, and chew toys for struggling dogs in shelters. The items we make will be donated to our partners, the Warrior Dog Rescue in Savage, MN, where they will be loved and appreciated by the pups until they find their forever homes.', 'Students who want to help animals in shelters through hands-on craft projects.', 'Paws for a Cause is a motivated student group created by Lily Kramer and Abby Britz focused on helping animals in need. Our mission is to provide meaningful donations, care, and support to rescue dogs in animal shelters. Members of our club will create collars, tie-blankets, and chew toys for struggling dogs in shelters. The items we make will be donated to our partners, the Warrior Dog Rescue in Savage, MN, where they will be loved and appreciated by the pups until they find their forever homes.', 'C420', 'Every other Monday or Wednesday', '7:40-8:10 a.m.', true, array['Animal welfare', 'Dog rescue', 'Hands-on crafting', 'Community service', 'Low-commitment volunteering']::text[], '{"science_stem": 0, "arts_creative": 3, "health_medical": 0, "competitiveness": 0, "performing_arts": 0, "time_commitment": 1, "world_languages": 0, "trades_technical": 0, "community_service": 5, "cultural_identity": 0, "sports_recreation": 0, "team_vs_individual": 3, "academic_competition": 0, "computer_science_tech": 0, "leadership_government": 0, "leadership_opportunity": 1, "social_special_interest": 2, "public_speaking_emphasis": 0, "writing_media_journalism": 0, "business_entrepreneurship": 0, "environmental_sustainability": 0}'::jsonb, 'whspawsforcause', 'anne.hooton@wayzataschools.org', null, '["https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/paws-for-a-cause-1.png"]'::jsonb),
  ('pediatric-cancer-awareness', 'Pediatric Cancer Awareness (PCA)', 'Service & Leadership', 'Miriam Lejonvarn', 'Helping children with cancer and their families.', 'Students interested in supporting children with cancer and their families.', 'Pediatric Cancer Awareness (PCA) works to help children with cancer and their families, raising awareness of pediatric cancer alongside its service work.', 'C122', 'Second Tuesday of each month', 'Before school, 7:40-8:10 a.m.', true, array['Supporting children with cancer', 'Supporting families', 'Pediatric cancer awareness', 'Community service', 'Health and medicine']::text[], '{"science_stem": 0, "arts_creative": 0, "health_medical": 3, "competitiveness": 0, "performing_arts": 0, "time_commitment": 1, "world_languages": 0, "trades_technical": 0, "community_service": 5, "cultural_identity": 0, "sports_recreation": 0, "team_vs_individual": 3, "academic_competition": 0, "computer_science_tech": 0, "leadership_government": 0, "leadership_opportunity": 2, "social_special_interest": 1, "public_speaking_emphasis": 1, "writing_media_journalism": 0, "business_entrepreneurship": 0, "environmental_sustainability": 0}'::jsonb, null, 'frankrac000@isd284.com', null, '["https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/pediatric-cancer-awareness-1.png"]'::jsonb),
  ('quiz-bowl', 'Quiz Bowl', 'Academic Competition', 'Abigail Genise, Alexander Jazyk', 'Quiz Bowl is a fast-paced, buzzer-based academic competition where teams of four answer clue-based questions covering a wide range of academic topics including history, literature, science, geography, current events, and more. Players race to buzz in with the correct answer before their opponents.', 'Students who love trivia and general knowledge.', 'Quiz Bowl is a fast-paced, buzzer-based academic competition where teams of four answer clue-based questions covering a wide range of academic topics including history, literature, science, geography, current events, and more. Players race to buzz in with the correct answer before their opponents.', 'A218 (Ms. Genise''s room)', 'Thursdays', '3:30-5:00 p.m.', false, array['Trivia buff', 'Wide general knowledge', 'Enjoys both pop culture and academics', 'Fast recall', 'Competitive', 'A jack-of-all-trades learner']::text[], '{"science_stem": 1, "arts_creative": 1, "health_medical": 0, "competitiveness": 4, "performing_arts": 0, "time_commitment": 2, "world_languages": 0, "trades_technical": 0, "community_service": 0, "cultural_identity": 1, "sports_recreation": 0, "team_vs_individual": 3, "academic_competition": 4, "computer_science_tech": 0, "leadership_government": 0, "leadership_opportunity": 1, "social_special_interest": 2, "public_speaking_emphasis": 0, "writing_media_journalism": 0, "business_entrepreneurship": 0, "environmental_sustainability": 0}'::jsonb, 'wayzataquizbowl', 'wayzataquizbowl@gmail.com, abigail.genise@wayzataschools.org, alexander.jazyk@wayzataschools.org', null, '["https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/quiz-bowl-1.png", "https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/quiz-bowl-2.png"]'::jsonb),
  ('r-i-s-e-group', 'R.I.S.E Group', 'CTE', 'Clark Doten', 'Explore different career fields through group activities, internships and volunteering, so you can figure out what to pursue after high school.', 'Students who aren''t sure what they want to do after high school and want to try things out.', 'RISE Group is a student-led group at Wayzata High School that helps students explore different career fields so they can decide what they want to pursue after high school. We help students find clarity through group activities, internships and volunteering.', 'C406', 'Every other Wednesday', 'After school, 3:10-4:10 p.m.', true, array['Career pathways', 'Post-high-school interests', 'Internships', 'Volunteering', 'Exploring careers', 'Deciding what to do after high school', 'Group activities']::text[], '{"science_stem": 1, "arts_creative": 0, "health_medical": 1, "competitiveness": 0, "performing_arts": 0, "time_commitment": 2, "world_languages": 0, "trades_technical": 2, "community_service": 0, "cultural_identity": 0, "sports_recreation": 0, "team_vs_individual": 3, "academic_competition": 0, "computer_science_tech": 0, "leadership_government": 1, "leadership_opportunity": 2, "social_special_interest": 3, "public_speaking_emphasis": 0, "writing_media_journalism": 0, "business_entrepreneurship": 3, "environmental_sustainability": 0}'::jsonb, 'wayzataclubrise', 'clubrise2025@gmail.com', null, '["https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/r-i-s-e-group-1.png", "https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/r-i-s-e-group-2.png"]'::jsonb),
  ('robotics', 'Robotics', 'CTE', 'Riley Davis', 'Students research, design, fabricate and test a robot built to the criteria set by the FIRST Robotics competition. About 25 members each year, by application and interview.', 'Students in grades 10-12 interested in engineering, fabrication and coding, who can commit to a heavy build season.', 'Robotics members research, design, fabricate and test a robot that has to meet the criteria set by the FIRST Robotics competition. About 25 students take part each year. Membership is open to grades 10-12 through an application and interview before the school year starts, and participating in SkillsUSA first is recommended. Pre-season runs September through December with meetings twice a week after school. Build season starts in January, when the team meets at least four days a week, with more days added closer to competition. Competitions run from locals in the fall through regionals in March, nationals in April and state in May. All members help with outreach events during the school year.', null, null, null, false, array['Interested in engineering or computer science', 'Likes building and coding', 'Hands-on problem solver', 'Enjoys teamwork', 'Interested in mechanical, electrical, or software careers', 'Enjoys tinkering and design']::text[], '{"science_stem": 4, "arts_creative": 0, "health_medical": 0, "competitiveness": 4, "performing_arts": 0, "time_commitment": 5, "world_languages": 0, "trades_technical": 2, "community_service": 0, "cultural_identity": 0, "sports_recreation": 0, "team_vs_individual": 5, "academic_competition": 2, "computer_science_tech": 5, "leadership_government": 0, "leadership_opportunity": 2, "social_special_interest": 1, "public_speaking_emphasis": 0, "writing_media_journalism": 0, "business_entrepreneurship": 0, "environmental_sustainability": 0}'::jsonb, 'wayzatarobotics', null, null, '["https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/robotics-1.png", "https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/robotics-2.png"]'::jsonb),
  ('science-bowl', 'Science Bowl', 'Academic Competition', 'Amanda Laden', 'Fast-paced, buzzer-based Q&A quiz competition (DOE-sponsored) across physical science, math, biology, and earth science. Quick-recall format. This is the high school Science Bowl team.', 'Students who love science trivia and quick recall under pressure.', 'Fast-paced, buzzer-based Q&A quiz competition (DOE-sponsored) across physical science, math, biology, and earth science. Quick-recall format. This is the high school Science Bowl team.', null, 'Fridays', '3:30-4:45 p.m.', false, array['Loves fast-recall trivia', 'Strong across multiple sciences and math', 'Competitive', 'Thrives under pressure', 'Quick thinker', 'Enjoys buzzer-style competition']::text[], '{"science_stem": 5, "arts_creative": 0, "health_medical": 0, "competitiveness": 4, "performing_arts": 0, "time_commitment": 2, "world_languages": 0, "trades_technical": 0, "community_service": 0, "cultural_identity": 0, "sports_recreation": 0, "team_vs_individual": 3, "academic_competition": 4, "computer_science_tech": 0, "leadership_government": 0, "leadership_opportunity": 1, "social_special_interest": 1, "public_speaking_emphasis": 0, "writing_media_journalism": 0, "business_entrepreneurship": 0, "environmental_sustainability": 0}'::jsonb, 'wayzatasb', 'amanda.laden@wayzataschools.org', null, '["https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/science-bowl-1.png", "https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/science-bowl-2.png"]'::jsonb),
  ('science-olympiad', 'Science Olympiad', 'Academic Competition', 'Peter Maas', 'A 23-event team competition mixing study, lab and build events. More hands-on and project-oriented than Science Bowl; the season runs late September to the March state tournament.', 'Students who like building things and hands-on science, not just quizzing, and who want to compete at a high level.', 'Wayzata High School Science Olympiad is an academic team for students who love science, technology, engineering or math, or who just enjoy solving complex hands-on challenges.

Science Olympiad works much like an academic track meet. Instead of running or jumping, team members compete across 23 different events spanning nearly every scientific discipline imaginable, including biology, chemistry, physics, earth science, astronomy, coding and engineering.

Members pair up with partners and specialize in specific events. Depending on your interest, you focus on one, or a mix, of three event types. In study events you and a partner become subject-matter experts in a specialized field such as Astronomy, Anatomy & Physiology or Geological Mapping, studying advanced material, creating reference binders and cheat sheets, and tackling rigorous exams at competitions. In lab events such as Chemistry Lab or Forensics you put theory into practice, performing experiments, analyzing unknown chemicals or solving crime scenes under a strict time limit. In build events you spend the season designing, constructing and testing devices from scratch, such as bridges, rubber-band-powered airplanes or autonomous vehicles, to meet strict specs and perform precise tasks at tournaments.

Through the fall and winter, team members meet after school to study, run mock tests, conduct lab experiments and test build devices in the labs and hallways, and the team attends multiple invitational tournaments across the region to sharpen skills, tweak builds and refine strategies. Everything builds toward the Minnesota State Science Olympiad tournament, where the team competes for the state championship and a spot representing Minnesota at the National Science Olympiad tournament.

Whether you want to dive deep into a niche scientific topic, gain real hands-on engineering experience, build connections with like-minded peers or compete at the national level, Science Olympiad is a place to learn, build and win together.', null, 'Tuesdays, late September through March', 'Immediately after school', false, array['Hands-on builder', 'Likes labs and engineering challenges', 'Broad science interest', 'Astronomy', 'Forensics', 'Chemistry lab', 'Anatomy and physiology', 'Coding', 'Enjoys teamwork', 'Interested in STEM careers', 'National-level competition', 'Likes variety, mixing knowledge events with building events']::text[], '{"science_stem": 5, "arts_creative": 0, "health_medical": 0, "competitiveness": 4, "performing_arts": 0, "time_commitment": 4, "world_languages": 0, "trades_technical": 3, "community_service": 0, "cultural_identity": 0, "sports_recreation": 0, "team_vs_individual": 4, "academic_competition": 4, "computer_science_tech": 2, "leadership_government": 0, "leadership_opportunity": 1, "social_special_interest": 2, "public_speaking_emphasis": 0, "writing_media_journalism": 0, "business_entrepreneurship": 0, "environmental_sustainability": 1}'::jsonb, 'wayzataso', 'whsscienceolympiad@wayzataschools.org', null, '["https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/science-olympiad-1.png", "https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/science-olympiad-2.png"]'::jsonb),
  ('skills-usa', 'SkillsUSA', 'CTE', 'Kyle Swenson', 'Build hands-on technical and career skills through team projects and state competitions, across engineering, digital media, skilled trades and leadership.', 'Students interested in trades, technical careers, engineering or digital media, at any experience level.', 'SkillsUSA at Wayzata High School is a student-led club where you can build real-world career skills, hands-on technical expertise and confidence through team projects and state competitions. Whether you''re interested in engineering, digital media, skilled trades or leadership, we offer practical experience and networking opportunities for every passion.', 'D216', 'Thursdays', '3:30 p.m.', false, array['Interested in skilled trades like welding, automotive, construction, or electrical', 'Hands-on learner', 'Wants technical career preparation', 'Likes working with tools', 'Practical problem solver', 'Digital media', 'Engineering', 'Leadership and team projects', 'State competitions']::text[], '{"science_stem": 3, "arts_creative": 0, "health_medical": 0, "competitiveness": 3, "performing_arts": 0, "time_commitment": 3, "world_languages": 0, "trades_technical": 5, "community_service": 0, "cultural_identity": 0, "sports_recreation": 0, "team_vs_individual": 2, "academic_competition": 1, "computer_science_tech": 3, "leadership_government": 0, "leadership_opportunity": 2, "social_special_interest": 1, "public_speaking_emphasis": 1, "writing_media_journalism": 2, "business_entrepreneurship": 1, "environmental_sustainability": 0}'::jsonb, 'wayzata_skillsusa', 'kyle.swenson@wayzataschools.org', null, '["https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/skillsusa-1.png", "https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/skillsusa-2.png"]'::jsonb),
  ('spanish-club', 'Spanish Club', 'Language & Culture', 'Allison Jakucki, Monica Vlach', 'Spanish language and culture.', 'Students learning Spanish or interested in Spanish-speaking cultures.', 'Spanish Club gives students a space to practice Spanish and take part in cultural activities and events tied to Spanish-speaking cultures.', null, null, null, false, array['Interested in Spanish language and culture', 'Likes learning languages', 'Plans to use Spanish in a career such as healthcare, education, or business', 'Curious about other cultures']::text[], '{"science_stem": 0, "arts_creative": 1, "health_medical": 0, "competitiveness": 0, "performing_arts": 0, "time_commitment": 1, "world_languages": 5, "trades_technical": 0, "community_service": 0, "cultural_identity": 4, "sports_recreation": 0, "team_vs_individual": 3, "academic_competition": 0, "computer_science_tech": 0, "leadership_government": 0, "leadership_opportunity": 1, "social_special_interest": 2, "public_speaking_emphasis": 1, "writing_media_journalism": 0, "business_entrepreneurship": 0, "environmental_sustainability": 0}'::jsonb, null, null, null, '["https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/spanish-club-1.png"]'::jsonb),
  ('spec-student-political-engagement-center', 'SPEC: Student Political Engagement Center', 'Service & Leadership', 'Jonathon Zetzman', 'SPEC Wayzata fosters civic engagement through education and structured discussion. Joining SPEC allows students to get access to information about political engagement opportunities, a national network of like-minded peers, leadership opportunities on a national scale, and similar activities to encourage civic involvement.', 'Students interested in civic engagement.', 'SPEC Wayzata fosters civic engagement through education and structured discussion. Joining SPEC allows students to get access to information about political engagement opportunities, a national network of like-minded peers, leadership opportunities on a national scale, and similar activities to encourage civic involvement.', 'A413', 'Every other Wednesday', 'After school', true, array['Civic engagement', 'Discussion', 'Education', 'Politics and government', 'Voting and elections', 'Civic discussion and debate', 'Staying informed']::text[], '{"science_stem": 0, "arts_creative": 0, "health_medical": 0, "competitiveness": 0, "performing_arts": 0, "time_commitment": 1, "world_languages": 0, "trades_technical": 0, "community_service": 0, "cultural_identity": 0, "sports_recreation": 0, "team_vs_individual": 3, "academic_competition": 0, "computer_science_tech": 0, "leadership_government": 5, "leadership_opportunity": 3, "social_special_interest": 2, "public_speaking_emphasis": 2, "writing_media_journalism": 0, "business_entrepreneurship": 0, "environmental_sustainability": 0}'::jsonb, 'spec.wayzata', 'choudame000@isd284.com, jonathon.zetzman@wayzataschools.org', null, '["https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/spec-student-political-engagement-center-1.png", "https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/spec-student-political-engagement-center-2.png"]'::jsonb),
  ('speech', 'Speech', 'Academic Competition', 'Jerrod Nelson', 'Individual competitive public speaking in categories like extemporaneous, original oratory, and dramatic interpretation.', 'Students who enjoy public speaking or performance and want individual competition.', 'Speech is an individual competitive speaking activity with categories ranging from extemporaneous speaking (impromptu current events) to original oratory and dramatic/humorous interpretation. Competitors are judged on delivery, content, and performance.', null, 'Individual practices weekly; team meetings monthly', null, false, array['Enjoys public speaking', 'Performance-minded', 'A natural storyteller', 'Interested in broadcasting, law, teaching, or acting', 'Wants to build confidence and communication skills']::text[], '{"science_stem": 0, "arts_creative": 1, "health_medical": 0, "competitiveness": 4, "performing_arts": 3, "time_commitment": 3, "world_languages": 0, "trades_technical": 0, "community_service": 0, "cultural_identity": 0, "sports_recreation": 0, "team_vs_individual": 1, "academic_competition": 3, "computer_science_tech": 0, "leadership_government": 0, "leadership_opportunity": 1, "social_special_interest": 1, "public_speaking_emphasis": 5, "writing_media_journalism": 2, "business_entrepreneurship": 0, "environmental_sustainability": 0}'::jsonb, 'wayzataspeech', 'jerrod.nelson@wayzataschools.org', null, '["https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/speech-1.png", "https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/speech-2.png"]'::jsonb),
  ('sports-promotional-team', 'Sports Promotional Team', 'Visual & Written Arts', 'Chris Easton', 'Team of sports photographers, videographers, graphic designers, and marketers for games and events throughout the school year.', 'Students interested in sports media.', 'Sports Promotional Team is a group of sports photographers, videographers, graphic designers, and marketers for games and events throughout the school year.', 'E105', 'Most Thursdays, but frequency depends on how much information we need to give to the group', 'Before school, 7:40-8:10 a.m.', true, array['Sports photography', 'Sports videography', 'Graphic design', 'Marketing', 'Games', 'Events']::text[], '{"science_stem": 0, "arts_creative": 4, "health_medical": 0, "competitiveness": 0, "performing_arts": 0, "time_commitment": 3, "world_languages": 0, "trades_technical": 0, "community_service": 0, "cultural_identity": 0, "sports_recreation": 3, "team_vs_individual": 4, "academic_competition": 0, "computer_science_tech": 0, "leadership_government": 0, "leadership_opportunity": 3, "social_special_interest": 1, "public_speaking_emphasis": 0, "writing_media_journalism": 3, "business_entrepreneurship": 3, "environmental_sustainability": 0}'::jsonb, null, 'haskohar000@isd284.com', null, '["https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/sports-promotional-team-1.png"]'::jsonb),
  ('stress-management', 'Stress Management', 'Service & Leadership', 'Anne Hooton', 'Provide support and strategies for student dealing with stress and anxiety', 'Students dealing with stress and anxiety.', 'Stress Management provides support and strategies for students dealing with stress and anxiety.', 'C420', 'Every other Wednesday', 'Before school, 7:40-8:10 a.m.', true, array['Support', 'Strategies', 'Stress', 'Anxiety']::text[], '{"science_stem": 0, "arts_creative": 0, "health_medical": 4, "competitiveness": 0, "performing_arts": 0, "time_commitment": 1, "world_languages": 0, "trades_technical": 0, "community_service": 2, "cultural_identity": 0, "sports_recreation": 0, "team_vs_individual": 2, "academic_competition": 0, "computer_science_tech": 0, "leadership_government": 0, "leadership_opportunity": 1, "social_special_interest": 3, "public_speaking_emphasis": 0, "writing_media_journalism": 0, "business_entrepreneurship": 0, "environmental_sustainability": 0}'::jsonb, null, 'kramelil000@icloud.com', null, '["https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/stress-management-1.png"]'::jsonb),
  ('student-council', 'Student Council', 'Service & Leadership', 'Amy Swenson, Sarah Lagerquist', 'The school’s student government. Two ways in: run for the elected Senate in spring, or work on to the House in the fall. Both plan Homecoming, Prom, service drives and spirit events.', 'Students interested in leadership, event planning and representing their classmates — either by running for election or by joining the House in the fall.', 'Looking for a way to make a difference at Wayzata High School, build leadership skills and help create a stronger school community? Student Council is for you, and there are two ways to get involved.

The Student Council Senate is the representative body for students. Elections take place each spring, with election materials sent to all students in April. Senate members work with students and administration to address student concerns, improve school culture and plan some of the school’s most memorable events, including Homecoming, P.E.A.C.E., Sip-N-Study, Staff Appreciation Week, the Spring Drive-In Movie and Prom. Student Council also organizes fundraising and service events supporting organizations such as IOCP, Minnesota Children’s Hospital, NAMI and Fund-A-Need, which directly supports WHS students.

Not interested in running for an elected position? You can still be an important part of the council. Students have the opportunity to work on to the Student Council House at the beginning of each school year, and information is shared during Back-to-Business days in the fall. Members of the House develop their leadership skills serving on various committees, and they also belong to a student council family group, where they create events and activities that engage every member of the school community.

Wayzata’s Student Council has been recognized as a National Gold Council of Excellence by the National Association of Student Councils, a distinction that reflects its commitment to leadership, service and the WHS community.', null, 'Senate: twice a month on Mondays. House: first or second Tuesday of the month', 'Senate: during the school day. House: before school, 7:45-8:15 a.m.', false, array['Interested in leadership', 'Enjoys planning events', 'Organized', 'Outgoing', 'Full of school spirit', 'Wants a voice in the school', 'Willing to run for election', 'Committee work', 'Fundraising and service', 'Homecoming and Prom planning', 'Interested in management, politics, or organizing']::text[], '{"science_stem": 0, "arts_creative": 0, "health_medical": 0, "competitiveness": 1, "performing_arts": 0, "time_commitment": 3, "world_languages": 0, "trades_technical": 0, "community_service": 4, "cultural_identity": 0, "sports_recreation": 0, "team_vs_individual": 5, "academic_competition": 0, "computer_science_tech": 0, "leadership_government": 5, "leadership_opportunity": 5, "social_special_interest": 3, "public_speaking_emphasis": 3, "writing_media_journalism": 0, "business_entrepreneurship": 1, "environmental_sustainability": 0}'::jsonb, 'wayzatastuco', 'whsstudentcouncil@isd284.com', null, '["https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/student-council-1.png", "https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/student-council-2.png"]'::jsonb),
  ('super-mileage-team', 'Super Mileage Team', 'CTE', 'Ryan Ward', 'Engineering-focused: students build ultra-fuel-efficient vehicles and compete on miles-per-gallon.', 'Students interested in mechanical engineering and hands-on vehicle building.', 'Super Mileage Team is an engineering-focused club where students design and build ultra-fuel-efficient vehicles, competing against other schools on fuel economy.', null, null, null, false, array['Engineering-minded', 'Likes cars and mechanics', 'Hands-on builder', 'Interested in efficiency and sustainability', 'Enjoys design and testing', 'Interested in mechanical or automotive engineering']::text[], '{"science_stem": 4, "arts_creative": 0, "health_medical": 0, "competitiveness": 3, "performing_arts": 0, "time_commitment": 4, "world_languages": 0, "trades_technical": 3, "community_service": 0, "cultural_identity": 0, "sports_recreation": 0, "team_vs_individual": 4, "academic_competition": 1, "computer_science_tech": 2, "leadership_government": 0, "leadership_opportunity": 1, "social_special_interest": 1, "public_speaking_emphasis": 0, "writing_media_journalism": 0, "business_entrepreneurship": 0, "environmental_sustainability": 3}'::jsonb, null, null, null, '["https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/super-mileage-team-1.png", "https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/super-mileage-team-2.png"]'::jsonb),
  ('sustainable-swag-ss', 'Sustainable Swag (SS)', 'Visual & Written Arts', 'Leah Marshall', 'A get together for people who share love for fashion and designing. We will do fun crafts like doing embroidery on old shirts, bleaching patterns onto cloth, etc. Simple sewing techniques will be taught and some items maybe donated to shelters or other organizations. The goal is to repurpose old clothes into something you''d wear again or to make them aesthetically appealing for some other people in need.', 'Students interested in fashion and design.', 'Sustainable Swag (SS) is a get-together for people who share a love for fashion and designing. They do fun crafts such as embroidery on old shirts, bleaching patterns onto cloth, and teach simple sewing techniques. Some items may be donated to shelters or other organizations. The goal is to repurpose old clothes into something you can wear again or to make them aesthetically appealing for others in need.', 'A215', 'Every Thursday Afterschool (some weeks will be free depending on testing schedule and club member vote)', 'After school, 3:10-4:10 p.m.', true, array['Embroidery on old shirts', 'Bleaching patterns onto cloth', 'Simple sewing techniques', 'Repurposing old clothes', 'Fashion design']::text[], '{"science_stem": 0, "arts_creative": 5, "health_medical": 0, "competitiveness": 0, "performing_arts": 0, "time_commitment": 1, "world_languages": 0, "trades_technical": 1, "community_service": 3, "cultural_identity": 0, "sports_recreation": 0, "team_vs_individual": 2, "academic_competition": 0, "computer_science_tech": 0, "leadership_government": 0, "leadership_opportunity": 1, "social_special_interest": 2, "public_speaking_emphasis": 0, "writing_media_journalism": 0, "business_entrepreneurship": 0, "environmental_sustainability": 4}'::jsonb, 'sustainableswagwhs', 'xunuo000@isd284.com', null, '["https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/sustainable-swag-ss-2.png", "https://pqfchywvjinosvvph