  ('the-bizmark-exchange', 'The BizMark Exchange', 'CTE', 'Kowsar Mohamud', 'The BizMark Exchange aims to inspire and educate students about business, entrepreneurship, and marketing through hands-on experiences, great speakers, and real-world case studies. We strive to make business accessible and exciting for everyone, especially those new to the field.', 'Students new to business, entrepreneurship, and marketing.', 'The BizMark Exchange aims to inspire and educate students about business, entrepreneurship, and marketing through hands-on experiences, great speakers, and real-world case studies. We strive to make business accessible and exciting for everyone, especially those new to the field.', 'C409', 'First Monday of every month', 'After school, 3:10-4:10 p.m.', true, array['Business', 'Entrepreneurship', 'Marketing', 'Hands-on experiences', 'Guest speakers', 'Real-world case studies']::text[], '{"science_stem": 0, "arts_creative": 0, "health_medical": 0, "competitiveness": 0, "performing_arts": 0, "time_commitment": 1, "world_languages": 0, "trades_technical": 0, "community_service": 0, "cultural_identity": 0, "sports_recreation": 0, "team_vs_individual": 3, "academic_competition": 0, "computer_science_tech": 0, "leadership_government": 0, "leadership_opportunity": 2, "social_special_interest": 2, "public_speaking_emphasis": 0, "writing_media_journalism": 0, "business_entrepreneurship": 5, "environmental_sustainability": 0}'::jsonb, 'thebizmarkexchange', 'yadavver000@isd284.com, kowsar.mohamud@wayzataschools.org', null, '["https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/the-bizmark-exchange-1.png", "https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/the-bizmark-exchange-2.png"]'::jsonb),
