  ('trojan-of-god', 'Trojan of God', 'Language & Culture', 'Russell Petterson', 'This is a group where we speak about Jesus, and to those who want to seek a purpose, or a hope, this is a club for those who want to develop a relationship with Jesus.', 'Students who want to seek purpose or hope and develop a relationship with Jesus.', 'Trojan of God is a group where members speak about Jesus and for those who want to seek a purpose or hope, it is a club to develop a relationship with Jesus.', 'C417', 'Every week on Thursdays', 'After school, 3:10-4:10 p.m.', true, array['Jesus', 'Purpose', 'Hope', 'Relationship with Jesus']::text[], '{"science_stem": 0, "arts_creative": 0, "health_medical": 0, "competitiveness": 0, "performing_arts": 0, "time_commitment": 1, "world_languages": 0, "trades_technical": 0, "community_service": 0, "cultural_identity": 5, "sports_recreation": 0, "team_vs_individual": 3, "academic_competition": 0, "computer_science_tech": 0, "leadership_government": 0, "leadership_opportunity": 1, "social_special_interest": 2, "public_speaking_emphasis": 4, "writing_media_journalism": 0, "business_entrepreneurship": 0, "environmental_sustainability": 0}'::jsonb, 'trojanofgod', 'haosop000@isd284.com', null, '["https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/trojan-of-god-1.png", "https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/trojan-of-god-2.png"]'::jsonb),
  ('trojan-tribune-journalism-club', 'Trojan Tribune', 'Visual & Written Arts', 'Casey Zylla', 'To provide a digital newspaper for the students of Wayzata and bright light to achievements that go unnoticed while keeping everyone informed.', 'Students who want to stay informed about school news.', 'Trojan Tribune provides a digital newspaper for the students of Wayzata, shines a bright light on achievements that go unnoticed, and keeps everyone informed.', 'C218', 'Biweekly Thursday mornings', 'Before school, 7:40-8:10 a.m.', false, array['Enjoys writing and reporting', 'Curious about news and events', 'Likes interviewing', 'Enjoys photography', 'Interested in journalism, media, or communications', 'Works well on deadlines']::text[], '{"science_stem": 0, "arts_creative": 1, "health_medical": 0, "competitiveness": 0, "performing_arts": 0, "time_commitment": 2, "world_languages": 0, "trades_technical": 0, "community_service": 1, "cultural_identity": 0, "sports_recreation": 0, "team_vs_individual": 3, "academic_competition": 0, "computer_science_tech": 0, "leadership_government": 0, "leadership_opportunity": 2, "social_special_interest": 1, "public_speaking_emphasis": 0, "writing_media_journalism": 5, "business_entrepreneurship": 0, "environmental_sustainability": 0}'::jsonb, 'trojantribune', 'toliaane000@isd284.com', null, '["https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/trojan-tribune-journalism-club-1.png", "https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/trojan-tribune-journalism-club-2.png"]'::jsonb),
  ('volunteer-club', 'Volunteer Club', 'Service & Leadership', 'Brenda Badger', 'A community service and leadership organization with a portal of local volunteer opportunities. $55 to join, fall registration closes September 27.', 'Students who want a steady, organized way to find volunteer work and log service hours.', 'Volunteer Club is a community service and youth leadership organization. Members sign up for a variety of volunteer opportunities in the local community and get access to the club''s volunteer opportunities portal, Canvas course and more. Meetings are held once a month, with a Wednesday after-school option and a Thursday before-school option, in Auditorium 1 or 2 depending on the month.

Membership for the 2026-27 school year costs $55 and you register through EPay. Fall registration is open August 10 through September 27. Club capacity is limited to 1,000 members, and a second registration window may open January 8-18, 2027 if space allows. Members must be current 9-12 students at WHS.', 'Auditorium 1 or 2', 'Once a month, Wednesday after school or Thursday before school', null, false, array['Service-minded', 'Enjoys giving back', 'Community-focused', 'Wants a flexible, low-commitment service option', 'Empathetic', 'Wants to earn volunteer hours']::text[], '{"science_stem": 0, "arts_creative": 0, "health_medical": 0, "competitiveness": 0, "performing_arts": 0, "time_commitment": 1, "world_languages": 0, "trades_technical": 0, "community_service": 5, "cultural_identity": 0, "sports_recreation": 0, "team_vs_individual": 3, "academic_competition": 0, "computer_science_tech": 0, "leadership_government": 0, "leadership_opportunity": 1, "social_special_interest": 2, "public_speaking_emphasis": 0, "writing_media_journalism": 0, "business_entrepreneurship": 0, "environmental_sustainability": 1}'::jsonb, 'whsvolunteerclub', 'volunteerclub@wayzataschools.org', null, '["https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/volunteer-club-1.png", "https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/volunteer-club-2.png"]'::jsonb),
  ('wave-wayzata-actively-valuing-empathy', 'WAVE: Wayzata Actively Valuing Empathy', 'Service & Leadership', 'Cory Knudtson', 'WAVE is a student-led group at school that offers a safe space to destress. Bring your friends and come enjoy while we perform hands-on activities like making slime, lotion, hand sanitizer, lip balm, and other art projects. There is zero commitment, you are always welcome, and it is always free. Snacks are included!', 'Students interested in mental health support.', 'WAVE is a student-led group at school that offers a safe space to destress. Bring your friends and come enjoy while we perform hands-on activities like making slime, lotion, hand sanitizer, lip balm, and other art projects. There is zero commitment, you are always welcome, and it is always free. Snacks are included!', 'C415', 'Last Friday of every month', 'After school, 3:10-4:10 p.m.', true, array['Mental health', 'Detox activities', 'Stress relief', 'Schoolwork', 'Homework', 'Current events']::text[], '{"science_stem": 0, "arts_creative": 4, "health_medical": 2, "competitiveness": 0, "performing_arts": 0, "time_commitment": 1, "world_languages": 0, "trades_technical": 0, "community_service": 1, "cultural_identity": 0, "sports_recreation": 0, "team_vs_individual": 3, "academic_competition": 0, "computer_science_tech": 0, "leadership_government": 0, "leadership_opportunity": 1, "social_special_interest": 5, "public_speaking_emphasis": 0, "writing_media_journalism": 0, "business_entrepreneurship": 0, "environmental_sustainability": 0}'::jsonb, 'wayzatawave', 'riya.naikare@gmail.com, cory.knudtson@wayzataschools.org', null, '["https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/wave-wayzata-actively-valuing-empathy-1.png"]'::jsonb),
  ('wayzata-computer-science-group', 'Wayzata Computer Science Group', 'CTE', 'Riley Davis', 'Weekly hands-on computer science: Python and small projects early in the year, then machine learning, cybersecurity, web development and AI.', 'Students who want to actually build things with code, from first-time programmers to anyone eyeing a tech career.', 'Wayzata Computer Science Group meets weekly to teach members computer science topics, focusing on Python early in the year with fun projects that apply what members learn.

The group is built around teamwork, with group projects and team hackathons rather than solo work. Later in the year it introduces other computer science fields such as machine learning, cybersecurity, web development, and agentic uses of artificial intelligence, so members can dive deeper into whichever topics interest them as a possible career.', 'A144 in 1st Floor New A', 'Wednesdays', 'After school, 3:10-4:10 p.m.', true, array['Python programming', 'Beginner friendly', 'Group projects', 'Team hackathons', 'Machine learning', 'Cybersecurity', 'Web development', 'Artificial intelligence', 'Tech careers']::text[], '{"science_stem": 3, "arts_creative": 0, "health_medical": 0, "competitiveness": 1, "performing_arts": 0, "time_commitment": 3, "world_languages": 0, "trades_technical": 0, "community_service": 0, "cultural_identity": 0, "sports_recreation": 0, "team_vs_individual": 4, "academic_competition": 1, "computer_science_tech": 5, "leadership_government": 0, "leadership_opportunity": 2, "social_special_interest": 2, "public_speaking_emphasis": 1, "writing_media_journalism": 0, "business_entrepreneurship": 0, "environmental_sustainability": 0}'::jsonb, 'wayzata.csc', 'wayzata.compsciclub@gmail.com', null, '["https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/wayzata-computer-science-group-1.png", "https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/wayzata-computer-science-group-2.png"]'::jsonb),
  ('wayzata-immune', 'Wayzata Immune', 'CTE', 'Molly Davin', 'Improve health literacy and educate students on the immune system and public health', 'Students interested in public health and the immune system.', 'Wayzata Immune works to improve health literacy and educate students on the immune system and public health.', 'A213', 'Once a month, typically on a Tuesday', 'After school, 3:10-4:10 p.m.', true, array['Health literacy', 'Immune system', 'Public health', 'Health education']::text[], '{"science_stem": 3, "arts_creative": 0, "health_medical": 5, "competitiveness": 0, "performing_arts": 0, "time_commitment": 1, "world_languages": 0, "trades_technical": 0, "community_service": 2, "cultural_identity": 0, "sports_recreation": 0, "team_vs_individual": 3, "academic_competition": 0, "computer_science_tech": 0, "leadership_government": 0, "leadership_opportunity": 1, "social_special_interest": 1, "public_speaking_emphasis": 1, "writing_media_journalism": 0, "business_entrepreneurship": 0, "environmental_sustainability": 0}'::jsonb, null, 'karukadh000@isd284.com', null, '["https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/wayzata-immune-1.png"]'::jsonb),
  ('wayzata-inventors-group', 'Wayzata Inventors Group', 'Academic Competition', 'Brett Shand', 'Wayzata Inventors Group offers students the chance to design, build, and test innovative engineering projects in a collaborative, hands-on environment. Members tackle challenges ranging from structural design projects such as bridges and towers to more advanced experimental systems, developing strong problem-solving, creativity, and technical thinking skills. A central focus is guiding students through the development of official science-fair projects, supporting team formation based on shared interests, idea generation, research, prototyping, and testing, with structured mentorship to prepare for regional, state, and international competitions, including the International Science and Engineering Fair. The group aims to create a space where students pursue ambitious ideas, gain real project experience, and work toward producing high-quality, competition-ready research.', 'Students interested in engineering projects and science fair competitions.', 'Wayzata Inventors Group offers students the chance to design, build, and test innovative engineering projects in a collaborative, hands-on environment. Members tackle challenges ranging from structural design projects such as bridges and towers to more advanced experimental systems, developing strong problem-solving, creativity, and technical thinking skills. A central focus is guiding students through the development of official science-fair projects, supporting team formation based on shared interests, idea generation, research, prototyping, and testing, with structured mentorship to prepare for regional, state, and international competitions, including the International Science and Engineering Fair. The group aims to create a space where students pursue ambitious ideas, gain real project experience, and work toward producing high-quality, competition-ready research.', 'A315', 'Tuesdays', '3:30-5:00 p.m.', true, array['Engineering projects', 'Structural design', 'Bridges and towers', 'Experimental systems', 'Science fair projects', 'Competition preparation']::text[], '{"science_stem": 5, "arts_creative": 0, "health_medical": 0, "competitiveness": 4, "performing_arts": 0, "time_commitment": 4, "world_languages": 0, "trades_technical": 1, "community_service": 0, "cultural_identity": 0, "sports_recreation": 0, "team_vs_individual": 4, "academic_competition": 4, "computer_science_tech": 0, "leadership_government": 0, "leadership_opportunity": 1, "social_special_interest": 2, "public_speaking_emphasis": 1, "writing_media_journalism": 0, "business_entrepreneurship": 0, "environmental_sustainability": 0}'::jsonb, 'wayzatainventors88', 'rahulvinoth29@gmail.com, brett.shand@wayzataschools.org', null, '["https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/wayzata-inventors-group-3.png"]'::jsonb),
  ('wayzata-investment-competition-wic', 'Wayzata Investment Competition (WIC)', 'CTE', 'Colleen Regnier', 'WIC provides the opportunity for members to compete in two stock market games (the Wharton Stock Market Game and the BestPrep Stock Market Game), running weekly meetings to go over investing fundamentals alongside advanced topics, aiming to both maximize portfolio growth for competitive success and provide a base of knowledge to help members in the future.', 'Students interested in investing.', 'WIC provides the opportunity for members to compete in two stock market games (the Wharton Stock Market Game and the BestPrep Stock Market Game), running weekly meetings to go over investing fundamentals alongside advanced topics, aiming to both maximize portfolio growth for competitive success and provide a base of knowledge to help members in the future.', '2nd floor forum', 'Every other Friday', 'After school, 3:10-4:10 p.m.', true, array['Investing', 'Financial responsibility', 'Wharton Investing Competition', 'MN Stock Market Game']::text[], '{"science_stem": 0, "arts_creative": 0, "health_medical": 0, "competitiveness": 3, "performing_arts": 0, "time_commitment": 3, "world_languages": 0, "trades_technical": 0, "community_service": 0, "cultural_identity": 0, "sports_recreation": 0, "team_vs_individual": 3, "academic_competition": 3, "computer_science_tech": 0, "leadership_government": 0, "leadership_opportunity": 2, "social_special_interest": 1, "public_speaking_emphasis": 0, "writing_media_journalism": 0, "business_entrepreneurship": 5, "environmental_sustainability": 0}'::jsonb, 'wayzata_wic', 'narankar000@isd284.com, colleen.regnier@wayzataschools.org', null, '["https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/wayzata-inventors-group-1.png", "https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/wayzata-inventors-group-2.png"]'::jsonb),
  ('wayzata-k-pop-group', 'Wayzata K-Pop Group', 'Language & Culture', 'Jennifer Larson', 'The Wayzata K-Pop Group was started during Term 4 of the 2025–2026 school year by three dedicated students. K-pop is a massive global and local phenomenon, and ourgroup provides an inclusive, high-energy space at Wayzata High School for students to connect. We dive into Korean culture, practice the language, play interactive team games, and learn choreography covers. By keeping things highly organized throughout the 2026–2027 school year, we plan to show the WHS Activities Office that our group has the consistency and student passion to deserve official school sponsorship!', 'Students interested in K-pop and Korean culture.', 'Wayzata K-Pop Group was started during Term 4 of the 2025-2026 school year by three dedicated students. It offers an inclusive, high-energy space at Wayzata High School for students to connect through K-pop, Korean culture, language practice, interactive team games, and choreography covers. The group plans to remain highly organized throughout the 2026-2027 school year to demonstrate consistency and passion to the WHS Activities Office for official sponsorship.', 'A119', 'Every Wednesday', 'After school, 3:10-4:10 p.m.', true, array['K-pop', 'Korean culture', 'Korean language', 'Interactive team games', 'Choreography covers', 'Dance covers', 'Performing on stage']::text[], '{"science_stem": 0, "arts_creative": 2, "health_medical": 0, "competitiveness": 0, "performing_arts": 4, "time_commitment": 2, "world_languages": 4, "trades_technical": 0, "community_service": 0, "cultural_identity": 5, "sports_recreation": 0, "team_vs_individual": 3, "academic_competition": 0, "computer_science_tech": 0, "leadership_government": 0, "leadership_opportunity": 3, "social_special_interest": 2, "public_speaking_emphasis": 0, "writing_media_journalism": 0, "business_entrepreneurship": 0, "environmental_sustainability": 0}'::jsonb, null, 'gowdagia000@isd284.com', null, '["h