  ('wayzata-neuroscience', 'Wayzata Neuroscience', 'CTE', 'Gretchen Minnick', 'The purpose of this group is to help students learn more about the importance of neurology, while also providing interactive social events and opportunities for them to excel in.', 'Students interested in neuroscience and medicine.', 'Wayzata Neuroscience helps students learn more about the importance of neurology, while also providing interactive social events and opportunities for them to excel in.', 'C405', 'Last Friday of the month', 'After school, 3:10-4:10 p.m.', true, array['Neurology', 'Brain science', 'Interactive social events', 'Medicine careers']::text[], '{"science_stem": 4, "arts_creative": 0, "health_medical": 5, "competitiveness": 0, "performing_arts": 0, "time_commitment": 1, "world_languages": 0, "trades_technical": 0, "community_service": 0, "cultural_identity": 0, "sports_recreation": 0, "team_vs_individual": 3, "academic_competition": 0, "computer_science_tech": 0, "leadership_government": 0, "leadership_opportunity": 1, "social_special_interest": 2, "public_speaking_emphasis": 1, "writing_media_journalism": 0, "business_entrepreneurship": 0, "environmental_sustainability": 0}'::jsonb, null, 'shajan000@isd284.com', null, '["https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/wayzata-neuroscience-1.png"]'::jsonb),
  ('wayzata-philosophy', 'Wayzata Philosophy', 'Service & Leadership', 'Elyssa McIntyre', 'The purpose of our group is to engage in discussion about the whys of life and get to know a deeper sense of self and personal identity through educational and conversational meetings based philosophical topics.', 'Students who enjoy open discussion about life, meaning, and identity.', 'Wayzata Philosophy engages students in discussion about the whys of life, building a deeper sense of self and personal identity through educational and conversational meetings on philosophical topics.', 'A417', 'Bi-monthly', 'After school, 3:10-4:10 p.m.', true, array['Philosophical discussion', 'The big questions of life', 'Personal identity', 'Self-reflection']::text[], '{"science_stem": 0, "arts_creative": 0, "health_medical": 0, "competitiveness": 0, "performing_arts": 0, "time_commitment": 1, "world_languages": 0, "trades_technical": 0, "community_service": 0, "cultural_identity": 0, "sports_recreation": 0, "team_vs_individual": 3, "academic_competition": 0, "computer_science_tech": 0, "leadership_government": 0, "leadership_opportunity": 1, "social_special_interest": 4, "public_speaking_emphasis": 3, "writing_media_journalism": 0, "business_entrepreneurship": 0, "environmental_sustainability": 0}'::jsonb, null, 'zehndnol000@isd284.com', null, '["https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/wayzata-philosophy-1.png"]'::jsonb),
  ('wayzata-real-estate-team', 'Wayzata Real Estate Team', 'CTE', 'Timothy Masters', 'Wayzata Real Estate Team is a student-led organization created with three peers, where we host weekly sessions after school for students to learn about real estate. Through interactive activities, projects, simulations, and discussions, we aim to make real estate informative and engaging for our classmates who may be interested in pursuing real estate in the future.', 'Students who may be interested in pursuing real estate.', 'Wayzata Real Estate Team is a student-led organization created with three peers, where we host weekly sessions after school for students to learn about real estate. Through interactive activities, projects, simulations, and discussions, we aim to make real estate informative and engaging for our classmates who may be interested in pursuing real estate in the future.', 'C409 (Mr. Masters'' room)', 'Mondays', '3:30-4:30 p.m.', true, array['Real estate', 'Interactive activities', 'Projects', 'Simulations', 'Discussions']::text[], '{"science_stem": 0, "arts_creative": 0, "health_medical": 0, "competitiveness": 0, "performing_arts": 0, "time_commitment": 3, "world_languages": 0, "trades_technical": 0, "community_service": 0, "cultural_identity": 0, "sports_recreation": 0, "team_vs_individual": 3, "academic_competition": 0, "computer_science_tech": 0, "leadership_government": 0, "leadership_opportunity": 2, "social_special_interest": 2, "public_speaking_emphasis": 0, "writing_media_journalism": 0, "business_entrepreneurship": 5, "environmental_sustainability": 0}'::jsonb, 'wayzata.real.estate.team', 'wayzatarealestate.7@gmail.com, timothy.masters@wayzataschools.org', null, '["https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/wayzata-real-estate-team-1.png", "https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/wayzata-real-estate-team-2.png"]'::jsonb),
  ('wayzata-red-cross', 'Wayzata Red Cross', 'Service & Leadership', 'Jennifer Reynolds', 'Community service, leadership and volunteering in support of the American Red Cross mission.', 'Students who want to serve their community and take on leadership in service projects.', 'The Wayzata Red Cross Club is a way to get involved in your community through service, leadership and volunteer opportunities. Throughout the year we host projects and events that support the mission of the American Red Cross, from care packages for people in our area to larger service initiatives, while giving members meaningful ways to make an impact.', 'C113', 'Second Monday of the month', 'After school, 3:10-4:10 p.m.', true, array['American Red Cross', 'care packages', 'helping people', 'Volunteering', 'Service projects and events', 'Leadership through service', 'Supporting the American Red Cross mission']::text[], '{"science_stem": 0, "arts_creative": 0, "health_medical": 2, "competitiveness": 0, "performing_arts": 0, "time_commitment": 2, "world_languages": 0, "trades_technical": 0, "community_service": 5, "cultural_identity": 0, "sports_recreation": 0, "team_vs_individual": 3, "academic_competition": 0, "computer_science_tech": 0, "leadership_government": 0, "leadership_opportunity": 2, "social_special_interest": 1, "public_speaking_emphasis": 2, "writing_media_journalism": 0, "business_entrepreneurship": 0, "environmental_sustainability": 0}'::jsonb, 'wayzata.rcc', 'lpelkola20@icloud.com, kodthaar000@isd284.com, jennifer.reynolds@wayzataschools.org', null, '["https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/wayzata-red-cross-1.png", "https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/wayzata-red-cross-2.png"]'::jsonb),
  ('wayzata-she-leads', 'Wayzata She Leads', 'CTE', 'Darcy Hanley', 'A club for girls building confidence and practical life skills — public speaking, resume writing, personal finance — alongside college and career planning.', 'Girls who want to build confidence and practical life skills, and start thinking about college and career early.', 'SheLeads is a club at Wayzata High School designed to empower girls by helping them build confidence, develop valuable life skills and prepare for their futures.

Members meet new people and connect with like-minded girls while learning skills such as public speaking, resume building and personal finance. Through college and career quizzes, activities and group discussions, SheLeads provides a supportive environment to explore future opportunities and grow as a leader.', 'Room C121 (Ms. Hanley’s classroom)', 'Every other Tuesday', 'Before school, 7:40-8:10 a.m.', true, array['Building confidence', 'Public speaking', 'Resume building', 'Personal finance', 'Life skills', 'College preparation', 'Career readiness', 'Leadership for young women', 'Meeting new people', 'Networking']::text[], '{"science_stem": 0, "arts_creative": 0, "health_medical": 0, "competitiveness": 0, "performing_arts": 0, "time_commitment": 2, "world_languages": 0, "trades_technical": 0, "community_service": 0, "cultural_identity": 0, "sports_recreation": 0, "team_vs_individual": 3, "academic_competition": 0, "computer_science_tech": 0, "leadership_government": 3, "leadership_opportunity": 4, "social_special_interest": 3, "public_speaking_emphasis": 4, "writing_media_journalism": 0, "business_entrepreneurship": 3, "environmental_sustainability": 0}'::jsonb, 'whs_sheleads', 'sheleads.whs@gmail.com', null, '["https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/wayzata-she-leads-1.png"]'::jsonb),
  ('wayzata-unicef', 'Wayzata UNICEF', 'Service & Leadership', 'Timothy Masters', 'The purpose is to educate, advocate, and fundraise to support UNICEF''s global mission of protecting children''s rights.', 'Students interested in children''s rights, global issues, and fundraising.', 'Wayzata UNICEF educates, advocates, and fundraises in support of UNICEF''s global mission of protecting children''s rights.', 'C409', 'Third Wednesday of the month', 'After school, 3:10-4:10 p.m.', true, array['Children''s rights', 'Global issues', 'Advocacy', 'Fundraising', 'Community service']::text[], '{"science_stem": 0, "arts_creative": 0, "health_medical": 1, "competitiveness": 0, "performing_arts": 0, "time_commitment": 1, "world_languages": 0, "trades_technical": 0, "community_service": 5, "cultural_identity": 0, "sports_recreation": 0, "team_vs_individual": 3, "academic_competition": 0, "computer_science_tech": 0, "leadership_government": 3, "leadership_opportunity": 2, "social_special_interest": 1, "public_speaking_emphasis": 2, "writing_media_journalism": 0, "business_entrepreneurship": 0, "environmental_sustainability": 0}'::jsonb, null, 'songmun000@isd284.com', null, '["https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/wayzata-unicef-1.png", "https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/wayzata-unicef-2.png"]'::jsonb),
  ('we-have-spirit-bible-study', 'We Have Spirit Bible Study', 'Language & Culture', 'Sean Egan', 'A weekly Friday-morning Bible study with donuts, guest speakers, games and small-group discussion.', 'Students who want to learn more about Christianity or find a like-minded community at school.', 'We Have Spirit (WHS) Bible Study is a student-led group that meets weekly on Friday mornings. Members eat donuts, read the Bible, listen to guest speakers, play games and discuss deep topics in small groups.

If you are interested in learning more about Christianity, or in finding a like-minded community at school, WHS Bible Study is the place for you.', 'A314', 'Friday mornings weekly', 'Before school, 7:40-8:10 a.m.', true, array['Bible study', 'Christian fellowship', 'Faith community', 'Small-group discussion', 'Guest speakers', 'Games', 'Learning about Christianity', 'Meeting before school']::text[], '{"science_stem": 0, "arts_creative": 0, "health_medical": 0, "competitiveness": 0, "performing_arts": 0, "time_commitment": 3, "world_languages": 0, "trades_technical": 0, "community_service": 0, "cultural_identity": 5, "sports_recreation": 0, "team_vs_individual": 4, "academic_competition": 0, "computer_science_tech": 0, "leadership_government": 0, "leadership_opportunity": 1, "social_special_interest": 3, "public_speaking_emphasis": 0, "writing_media_journalism": 0, "business_entrepreneurship": 0, "environmental_sustainability": 0}'::jsonb, 'whs__bible_study', 'hvidslau000@isd284.com', null, '["https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/we-have-spirit-bible-study-1.png", "https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/we-have-spirit-bible-study-2.png"]'::jsonb),
  ('women-in-government', 'Women In Government', 'Service & Leadership', 'Elizabeth Hansen', 'Women in Government is a student organization to support students interested in government, public policy, and political careers while exploring the role of women in politics today. Members will have opportunities to build public speaking and leadership skills through discussions, guest speakers, and occasional research or presentation projects that educate others on current issues. The club will also connect students with women working in government and public service through guest visits and opportunities through that.', 'Students interested in government and civic leadership.', 'Women in Government is a student organization to support students interested in government, public policy, and political careers while exploring the role of women in politics today. Members will have opportunities to build public speaking and leadership skills through discussions, guest speakers, and occasional research or presentation projects that educate others on current issues. The club will also connect students with women working in government and public service through guest visits and opportunities through that.', 'A414', 'Every other Monday', 'After school, 3:10-4:10 p.m.', true, array['Government', 'Public policy', 'Civic leadership', 'Women in government', 'Student involvement']::text[], '{"science_stem": 0, "arts_creative": 0, "health_medical": 0, "competitiveness": 0, "performing_arts": 0, "time_commitment": 2, "world_languages": 0, "trades_technical": 0, "community_service": 0, "cultural_identity": 0, "sports_recreation": 0, "team_vs_individual": 3, "academic_competition": 0, "computer_science_tech": 0, "leadership_government": 5, "leadership_opportunity": 2, "social_special_interest": 0, "public_speaking_emphasis": 2, "writing_media_journalism": 0, "business_entrepreneurship": 0, "environmental_sustainability": 0}'::jsonb, 'womeningovmn', 'isha.gaur016@gmail.com, elizabeth.hansen@