  ('youth-in-medicine', 'Youth in Medicine', 'CTE', 'Mr. Downing', 'The purpose of our group is to spark thought-provoking conversations around the medical field and the careers within it. Through hands-on labs and demonstrations, we hope to engage the students at Wayzata to pursue careers in healthcare.', 'Students interested in medical careers.', 'Youth in Medicine sparks thought-provoking conversations about the medical field and its careers. It offers hands-on labs and demonstrations to engage students.', 'A219', 'First Wednesday of the month', 'After school, 3:10-4:10 p.m.', true, array['Medical field', 'Healthcare careers', 'Hands-on labs', 'Demonstrations', 'Thought-provoking conversations']::text[], '{"science_stem": 2, "arts_creative": 0, "health_medical": 5, "competitiveness": 0, "performing_arts": 0, "time_commitment": 2, "world_languages": 0, "trades_technical": 0, "community_service": 0, "cultural_identity": 0, "sports_recreation": 0, "team_vs_individual": 3, "academic_competition": 0, "computer_science_tech": 0, "leadership_government": 0, "leadership_opportunity": 2, "social_special_interest": 2, "public_speaking_emphasis": 2, "writing_media_journalism": 0, "business_entrepreneurship": 0, "environmental_sustainability": 0}'::jsonb, 'wayzatayouthinmed', 'helmmeg000@isd284.com', null, '["https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/youth-in-medicine-1.png", "https://pqfchywvjinosvvphshy.supabase.co/storage/v1/object/public/club-photos/youth-in-medicine-2.png"]'::jsonb)
